function _cgoApplyAllDynamicTexts(lang, p) {
  if(!p) p = CGO_I18N[lang] || CGO_I18N['ko'];

  // ─── 1. 배너 텍스트 ───
  var _bnr = document.getElementById('cgoBannerText');
  if(_bnr && p.banner_full) _bnr.innerHTML = p.banner_full;

  // ─── 2. 자동 계산 활성화 조건 (calcReadyHint) ───
  var hintTitle = document.getElementById('calcReadyHint')&&document.getElementById('calcReadyHint').querySelector('div[style*="font-weight:800"]');
  if(hintTitle) hintTitle.textContent = p.calc_ready_title || '⚡ 자동 계산 활성화 조건';

  // ─── 3. calcReadyList 항목 (JS로 동적 생성되므로 _checkCalcReady 언어 적용) ───
  window._calcReadyLang = p; // _checkCalcReady에서 참조
  if(typeof _checkCalcReady === 'function') _checkCalcReady();

  // ─── 4. 생체 스캔 버튼 텍스트 ───
  var scanMap = [
    {id:'scan_face_title', sel:'#page-dashboard'},
    {id:'scan_palm_title', sel:'#page-dashboard'},
    {id:'scan_tongue_title', sel:'#page-dashboard'},
    {id:'scan_breath_title', sel:'#page-dashboard'},
    {id:'scan_face_sub', sel:'#page-dashboard'},
    {id:'scan_palm_sub', sel:'#page-dashboard'},
    {id:'scan_tongue_sub', sel:'#page-dashboard'},
    {id:'scan_breath_sub', sel:'#page-dashboard'},
    {id:'see_instructions', sel:'#page-dashboard'},
    {id:'voice_guide', sel:'#page-dashboard'},
    {id:'voice_on_desc', sel:'#page-dashboard'},
    {id:'time_unknown', sel:'#page-dashboard'},
    {id:'todayFortune', sel:'#page-dashboard'},
    {id:'todayFortuneDesc', sel:'#page-dashboard'},
  ];
  scanMap.forEach(function(m){
    document.querySelectorAll('[data-i18n="'+m.id+'"]').forEach(function(el){
      if(p[m.id]) el.textContent = p[m.id];
    });
  });

  // ─── 5. option 요소 (시간 모름 등) ───
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var k = el.getAttribute('data-i18n');
    if(p[k] !== undefined) el.textContent = p[k];
  });

  // ─── 6. MSP 섹션 ───
  var mspBackBtn = document.querySelector('#page-dashboard [onclick*="mspBack"], #page-dashboard .msp-back');
  if(mspBackBtn && p.btn_back) mspBackBtn.textContent = p.btn_back || '← 되돌리기';

  // ─── 7. 전체 페이지 data-i18n 재적용 ───
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var k = el.getAttribute('data-i18n');
    if(p[k] !== undefined) el.textContent = p[k];
  });
  document.querySelectorAll('[data-i18n-html]').forEach(function(el){
    var k = el.getAttribute('data-i18n-html');
    if(p[k] !== undefined) el.innerHTML = p[k];
  });

  // ─── 8. 숨겨진 오버레이/팝업도 번역 ───
  ['todayFortuneOverlay','stk-ai-overlay','bsFullWrap','fortunePopupOverlay'].forEach(function(id){
    var ov = document.getElementById(id);
    if(!ov) return;
    ov.querySelectorAll('[data-i18n]').forEach(function(el){
      var k = el.getAttribute('data-i18n');
      if(p[k] !== undefined) el.textContent = p[k];
    });
  });

  // ─── 9. CGO-MASTER 동기화 텍스트 ───
  var masterSpan = document.querySelector('#cgoMasterStatus span[style*="font-weight:700"]');
  if(masterSpan) masterSpan.textContent = p.cgo_master_sync || 'CGO-MASTER 유기체 동기화 완료';

  // ─── 10. 오늘의 운세 카드 ON 배지들 ───
  document.querySelectorAll('#today-fortune-preview span').forEach(function(el, i){
    var badges = [p.nasa_badge||'NASA ON', p.engine50_badge||'50대 역학', p.bio_badge||'실시간 생체'];
    if(badges[i]) el.textContent = badges[i];
  });

  // ─── 11. JS 동적 생성 텍스트 직접 교체 ───
  // CGO 소개 텍스트
  document.querySelectorAll('[data-i18n="cgo_intro"]').forEach(function(el){
    if(p.cgo_intro) el.textContent = p.cgo_intro;
  });
  // 생체 주의사항
  document.querySelectorAll('[data-i18n="bio_caution1"]').forEach(function(el){
    if(p.bio_caution1) el.textContent = p.bio_caution1;
  });
  document.querySelectorAll('[data-i18n="bio_caution2"]').forEach(function(el){
    if(p.bio_caution2) el.textContent = p.bio_caution2;
  });
  // 역학 카드 라벨
  document.querySelectorAll('[data-i18n="eng20_cross"]').forEach(function(el){
    if(p.eng20_cross) el.textContent = p.eng20_cross;
  });
  document.querySelectorAll('[data-i18n="tap_detail"]').forEach(function(el){
    if(p.tap_detail) el.textContent = p.tap_detail;
  });

  // ─── 12. JS 생성 동적 텍스트 (innerHTML 교체) ───
  // CGO-MASTER 상태
  var _ms = document.getElementById('cgoMasterStatus');
  if(_ms) {
    var _msSpan = _ms.querySelector('span[style*="font-weight:700"]');
    if(_msSpan && p.cgo_master_sync) _msSpan.textContent = p.cgo_master_sync;
  }
  // 탭하여 상세보기 (JS로 생성된 것)
  document.querySelectorAll('.fortune-card-tap, [data-tap-detail]').forEach(function(el){
    if(p.tap_detail) el.textContent = p.tap_detail;
  });

  // ─── 13. 페이지별 특수 번역 ───
  // 스캔 페이지 - CGO-FULI 소개 배너
  var _scanIntro = document.querySelector('#page-scan [data-i18n="cgo_intro"]');
  if(_scanIntro && p.cgo_intro) _scanIntro.textContent = p.cgo_intro;

  // ─── 14. 모든 숨겨진 페이지 data-i18n 적용 ───
  document.querySelectorAll('.page').forEach(function(pg){
    pg.querySelectorAll('[data-i18n]').forEach(function(el){
      var k = el.getAttribute('data-i18n');
      if(p[k] !== undefined) el.textContent = p[k];
    });
    pg.querySelectorAll('[data-i18n-html]').forEach(function(el){
      var k = el.getAttribute('data-i18n-html');
      if(p[k] !== undefined) el.innerHTML = p[k];
    });
  });

  console.log('[CGO-번역] 동적 텍스트 적용 완료:', lang);
}


// ── 팝업 번역 트리거 헬퍼 ─────────────────────────────────────
function _cgoTransPopup(elId) {
  if (!window._LANG || window._LANG === 'ko') return;
  var el = document.getElementById(elId);
  if (!el) return;
  var p = CGO_I18N[window._LANG];
  if (!p) return;
  clearTimeout(window._cgoPopupTransTimer);
  window._cgoPopupTransTimer = setTimeout(function(){
    console.log('[CGO팝업번역] elId='+elId+' lang='+window._LANG);
    if (typeof _cgoAiTranslatePage === 'function') {
      _cgoAiTranslatePage(window._LANG, p, el);
    }
  }, 200);
}

function _cgoSaveSnap() {
  // 이미 저장됐으면 건너뜀 (단, ko 복원 직후면 재저장)
  if (_cgoOrigSnap && _cgoOrigSnap.length > 0) return;
  _cgoOrigSnap = [];
  // 전체 body에서 저장 (원본 한국어 보존용)
  var skip = {SCRIPT:1,STYLE:1,NOSCRIPT:1,CANVAS:1,SVG:1,INPUT:1,TEXTAREA:1,CODE:1};
  function walk(node) {
    if (node.nodeType === 3) {
      var t = node.nodeValue.trim();
      if (t.length >= 2 && /[가-힣]/.test(t)) _cgoOrigSnap.push({node:node, text:node.nodeValue});
    } else if (node.nodeType === 1 && !skip[node.tagName]) {
      for (var i=0; i<node.childNodes.length; i++) walk(node.childNodes[i]);
    }
  }
  walk(document.body);
  // ★ 최초 한국어 스냅 영구 보존 (언어 전환 기준점)
  if(!window._cgoInitialKoSnap && _cgoOrigSnap && _cgoOrigSnap.length>0){
    window._cgoInitialKoSnap=_cgoOrigSnap.map(function(it){return{node:it.node,text:it.text};});
  }
}

function _cgoRestoreTexts() {
  // ★ 항상 최초 한국어 스냅으로 복원 (짬뽕 방지)
  var snap = window._cgoInitialKoSnap || _cgoOrigSnap;
  if(!snap) return;
  snap.forEach(function(item){ try{item.node.nodeValue=item.text;}catch(e){} });
}

// ── 번역 대상 텍스트 노드 수집 ────────────────────────────────
function _cgoGetNodes(rootEl) {
  var skip = {SCRIPT:1,STYLE:1,NOSCRIPT:1,CANVAS:1,SVG:1,INPUT:1,TEXTAREA:1,CODE:1};
  var result = [];
  var root = rootEl || document.body;
  function walk(node) {
    if (node.nodeType === 3) {
      var t = node.nodeValue.trim();
      if (t.length >= 2 && /[가-힣]/.test(t)) {
        var par = node.parentElement;
        if (par && (par.getAttribute('data-i18n') || par.getAttribute('data-i18n-html'))) return;
        // rootEl 없을 때 — 모든 페이지 스캔 (숨겨진 페이지 포함)
        // ★ 제외: cgoEntrance (대문) 안의 텍스트는 phase0에서 처리
        if (!rootEl && par) {
          var _entrance = par.closest && par.closest('#cgoEntrance');
          if (_entrance) return; // 대문은 제외
        }
        result.push(node);
      }
    } else if (node.nodeType === 1 && !skip[node.tagName]) {
      for (var i=0; i<node.childNodes.length; i++) walk(node.childNodes[i]);
    }
  }
  walk(root);
  return result;
}

