// 볼 색상 클래스
function ballClass(n) {
  if(n<=10) return 'ball-1-10';
  if(n<=20) return 'ball-11-20';
  if(n<=30) return 'ball-21-30';
  if(n<=40) return 'ball-31-40';
  return 'ball-41-45';
}

// 볼 HTML 생성
function makeBall(n, isBonus, energy) {
  // 황금 오라: 에너지 90점 이상 최고 에너지 번호
  var aura = (!isBonus && energy && energy >= 90) ? ' gold-aura' : '';
  return '<div class="lotto-ball '+(isBonus?'bonus':ballClass(n))+aura+'"'+(isBonus?' title="보너스"':' title="에너지 '+( energy||'')+' "')+'>'+n+'</div>';
}

