function makeSmallBall(n) {
  var colors={'1-10':'#d97706','11-20':'#2563eb','21-30':'#dc2626','31-40':'#a0afc0','41-45':'#059669'};
  var c=n<=10?'1-10':n<=20?'11-20':n<=30?'21-30':n<=40?'31-40':'41-45';
  return '<div class="lh-ball" style="background:'+colors[c]+'">'+n+'</div>';
}

// 시드 기반 난수 (재현 가능)
function ltRng(s){ return ((s*1103515245+12345)&0x7fffffff); }

function ltSeed(y,m,d,ln,week) {
  var now = new Date();
  // 시간 요소: 시 단위로 번호가 달라짐
  var hourFactor = now.getHours() * 53 + Math.floor(now.getMinutes()/10) * 7;
  // 생체 요소
  var bioFactor = 0;
  if(window._baiScanned && window.appState && window.appState.bio){
    var b = window.appState.bio;
    bioFactor = Math.round((b.hrv||0)*11 + (b.fci||0)*7 + (b.bli||0)*5);
  }
  if(window.BS && window.BS.tongueData){
    bioFactor += (window.BS.tongueData.tliScore||0) * 13;
  }
  // NASA 행성 (목성·태양 위주 — 행운 관련)
  var nasaFactor = 0;
  if(window._nasaPlanets){
    var p = window._nasaPlanets;
    if(p.jupiter) nasaFactor += Math.round(p.jupiter.lon * 7);
    if(p.sun)     nasaFactor += Math.round(p.sun.lon * 3);
    if(p.moon)    nasaFactor += Math.round(p.moon.lon * 5);
  }
  var s = (y*397 + m*41 + d*13 + (ln||5)*17 + hourFactor + bioFactor + nasaFactor);
  s=(s*1103515245+12345)&0x7fffffff;
  return s;
}

// 번호 풀에서 중복없이 N개 선택
function pickFromPool(pool, n, seed) {
  var arr=[].concat(pool);
  var result=[];
  while(result.length < n && arr.length > 0) {
    seed=ltRng(seed);
    var idx=seed%arr.length;
    var num=arr.splice(idx,1)[0];
    if(num>=1 && num<=45 && result.indexOf(num)<0) result.push(num);
  }
  return {nums:result, seed:seed};
}

// 에너지 점수 계산
function calcLottoEnergy(nums, domOh, lifeNum) {
  var score=55;
  var ohRange=OH_LUCKY_RANGES[domOh]||{primary:[],secondary:[]};
  nums.forEach(function(n){
    if(ohRange.primary.indexOf(n)>=0) score+=4;
    else if(ohRange.secondary.indexOf(n)>=0) score+=2;
    var lifeArr=LIFE_LUCKY[lifeNum]||[];
    if(lifeArr.indexOf(n)>=0) score+=3;
  });
  return Math.min(98, score);
}

// 번호 근거 태그 생성
function makeBasisTags(nums, domOh, lifeNum, method) {
  var domOhEn={목:'Wood',화:'Fire',토:'Earth',금:'Metal',수:'Water'}[domOh]||domOh;
  var tags=[];
  var ohRange=OH_LUCKY_RANGES[domOh]||{primary:[],secondary:[]};
  var lifeArr=LIFE_LUCKY[lifeNum]||[];
  var ohCount=nums.filter(function(n){return ohRange.primary.indexOf(n)>=0;}).length;
  var lifeCount=nums.filter(function(n){return lifeArr.indexOf(n)>=0;}).length;
  if(ohCount>0) tags.push(_cgoTP('{0}오행 {1}개','{1} {0} element'+(ohCount>1?'s':''),(window._LANG&&window._LANG!=='ko')?domOhEn:domOh,ohCount));
  if(lifeCount>0) tags.push((typeof _cgoT==='function'?_cgoT((typeof _cgoT==='function'?_cgoT('생명수'):'생명수')):(typeof _cgoT==='function'?_cgoT('생명수'):'생명수'))+lifeNum+(typeof _cgoT==='function'?_cgoT(' 연동'):' 연동'));
  var methodTags=(function(){var _T=(typeof _cgoT==='function')?_cgoT:function(x){return x;};return{
    all18:_T('18대역학 통합'), all:_T('18대역학 통합'),
    jami:_T('자미두수 반영'), astro:_T('달자리 반영'),
    nasa18:'NASA Real-time', kabala:_T('세피로트 연동'),
    tarot:_T('달위상×타로'), taeul:_T('태을신수 시진'),
    gmd:_T('기문방위 연동')
  };})();
  if(methodTags[method]) tags.push(methodTags[method]);
  tags.push(_cgoTX('합계 ','Total ')+(nums.reduce(function(a,b){return a+b;},0)));
  return tags.map(function(t){return '<span class="ball-tag">'+t+'</span>';}).join('');
}

