// 🔗 CGo-Fuli-ZALOU 데이터 서버 연동
// https://gh951.github.io/CGo-Fuli-ZALOU/
// C-24 · 2026.05
// ══════════════════════════════════════════════════
var _ZALOU_BASE = 'https://gh951.github.io/CGo-Fuli-ZALOU';
var _ZALOU_LOADED = {mok:false,hwa:false,to:false,geum:false,su:false};

function _zalou_loadHanja(oh, fname, callback){
  if(_ZALOU_LOADED[fname]) { if(callback) callback(); return; }
  fetch(_ZALOU_BASE+'/hanja/'+fname+'.json')
    .then(function(r){ return r.json(); })
    .then(function(data){
      if(Array.isArray(data) && data.length > 0){
        // 기존 내장 DB에 병합 (중복 kr 제거)
        var existing = (HANJA_DB[oh]||[]).map(function(h){return h.kr;});
        var added = 0;
        data.forEach(function(h){
          if(!existing.includes(h.kr)){
            HANJA_DB[oh].push(h);
            added++;
          }
        });
        _ZALOU_LOADED[fname] = true;
        console.log('✅ ZALOU 한자 로드: '+oh+'('+fname+') +'+added+'자 → 총 '+HANJA_DB[oh].length+'자');
      }
      if(callback) callback();
    })
    .catch(function(e){
      console.log('⚠️ ZALOU 로드 실패('+fname+'), 내장 DB 사용:', e.message);
      if(callback) callback();
    });
}

function _zalou_loadBrand(cat, callback){
  fetch(_ZALOU_BASE+'/brand/'+cat+'.json')
    .then(function(r){ return r.json(); })
    .then(function(data){
      if(data && typeof data === 'object'){
        // BIZ_NAMES에 병합
        if(!BIZ_NAMES[cat]) BIZ_NAMES[cat] = {};
        Object.keys(data).forEach(function(style){
          if(!BIZ_NAMES[cat][style]) BIZ_NAMES[cat][style] = [];
          BIZ_NAMES[cat][style] = BIZ_NAMES[cat][style].concat(data[style]);
        });
        console.log('✅ ZALOU 브랜드 로드: '+cat);
      }
      if(callback) callback();
    })
    .catch(function(e){
      console.log('⚠️ ZALOU 브랜드 실패('+cat+'):', e.message);
      if(callback) callback();
    });
}

// 작명 시작 시 해당 오행 자동 로드
function _zalou_preload(domOh, bizCat){
  var ohMap = {'목':'mok','화':'hwa','토':'to','금':'geum','수':'su'};
  var fname = ohMap[domOh];
  if(fname && !_ZALOU_LOADED[fname]){
    _zalou_loadHanja(domOh, fname);
  }
  // 브랜드 카테고리 로드
  if(bizCat) _zalou_loadBrand(bizCat);
}

