// 전문가 토글 함수
function toggle18Expert(cid) {
  var xEl = document.getElementById(cid+'_exp');
  var btnEl = document.getElementById(cid+'_btn');
  if(!xEl) return;
  var showing = xEl.style.display !== 'none';
  xEl.style.display = showing ? 'none' : 'block';
  if(btnEl) {
    btnEl.textContent = showing ? _cgoTX('전문가▾','Expert ▾') : _cgoTX('접기▲','Collapse ▲');
    btnEl.style.background = showing ? 'rgba(212,168,67,.12)' : 'rgba(212,168,67,.25)';
  }
}

// 18개 카드 그리드 HTML 생성 — easy/expert 토글 포함
window._nmToggleMore=function(btn){ try{ var e=document.getElementById('nmMoreEng'); if(!e)return; var sh=(e.style.display==='none'); e.style.display=sh?'block':'none'; btn.textContent=sh?(typeof _cgoT==='function'?_cgoT('접기 ▲'):'접기 ▲'):(typeof _cgoT==='function'?_cgoT('🔍 더보기 — 나머지 역학 분석'):'🔍 더보기 — 나머지 역학 분석'); }catch(err){} };
function build18Cards(scores, context, _lottoMethod) {
  var _lottoIds = null;
  if(context === 'lotto' && _lottoMethod) {
    var _M2ID = {
      saju:['saju'], jami:['jami'], astro:['solar','natal'], num:['wesnum'],
      gmd:['gimu'], kusei:['kusei'], tarot:['tarot'], kabala:['kabala'],
      taeul:['taeul'], juyeok:['juyeok'], yukrim:['yukrim'], seong:['seong'], pungsu:['pungsu']
    };
    var _base = _lottoMethod.replace('+nasa','').replace('+bio','');
    var _hasN = _lottoMethod.indexOf('+nasa')>=0 || _lottoMethod==='nasa18';
    var _hasB = _lottoMethod.indexOf('+bio')>=0;
    var _isAll = (_base==='all18'||_base==='nasa18'||_base.indexOf('all')>=0);
    if(!_isAll) {
      _lottoIds = _M2ID[_base] || null;
      if(_lottoIds && _hasN) ['solar','natal','transit','house'].forEach(function(id){
        if(_lottoIds.indexOf(id)<0) _lottoIds.push(id);
      });
      if(_lottoIds && _hasB) ['songeum','gwansang'].forEach(function(id){
        if(_lottoIds.indexOf(id)<0) _lottoIds.push(id);
      });
    }
  }
  function _lottoFilter(s){ if(s.id==='kusei') return (context==='lotto') && (!_lottoIds || _lottoIds.indexOf('kusei')>=0); return !_lottoIds || _lottoIds.indexOf(s.id)>=0; }
  var _nmCore={saju:1,seong:1,jami:1,juyeok:1};
  var p = window._nasaPlanets;
  var nasaTag = p
    ? '<span style="font-size:9px;background:rgba(52,211,153,.15);color:#34d399;border:1px solid rgba(52,211,153,.3);border-radius:4px;padding:1px 6px;margin-left:4px">🛰 NASA 실시간</span>'
    : '<span style="font-size:9px;background:rgba(255,255,255,.05);color:var(--text-3);border:1px solid rgba(255,255,255,.1);border-radius:4px;padding:1px 6px;margin-left:4px">⚡계산 후 NASA 연동</span>';

  function makeCard(sys, isWest) {
    // ✦ 정직 원칙: 행운 번호 페이지에서 미검사 역학은 0점 + 검사하기 → ✦
    var needsCheck = false;
    var checkKind = null;
    if (context === 'lotto') {
      if (sys.id === 'tarot' && !(window._qt && window._qt.selectedCard)) {
        needsCheck = true; checkKind = 'tarot';
      } else if (sys.id === 'gwansang' && !(window._bioSkinData && window._bioSkinData.face)) {
        needsCheck = true; checkKind = 'face';
      } else if (sys.id === 'songeum' && !(window._bioSkinData && window._bioSkinData.palm)) {
        needsCheck = true; checkKind = 'palm';
      }
    }

    var sc = scores[sys.id] || {score:70, easy:'분석 중...', expert:'분석 중...'};
    var bar = needsCheck ? 0 : Math.min(99, Math.round(sc.score));
    var col = needsCheck
      ? 'rgba(148,163,184,.5)'
      : (isWest
        ? (bar>=85?'#a78bfa':bar>=70?'#60a5fa':'#38bdf8')
        : (bar>=85?'#d4a843':bar>=70?'#34d399':'#38bdf8'));
    var bg = needsCheck ? 'rgba(148,163,184,.04)' : (isWest ? 'rgba(167,139,250,.04)' : 'rgba(255,255,255,.03)');
    var bdr = needsCheck ? 'rgba(148,163,184,.18)' : (isWest ? 'rgba(167,139,250,.12)' : 'rgba(255,255,255,.08)');
    var cid = 'c18_'+context+'_'+sys.id;

    // 미검사면 해설 자리에 안내문, 검사 완료면 기존 해설
    var easyTxt = needsCheck
      ? '🔒 <b style="color:rgba(212,168,67,.7)">검사 후 분석 가능합니다</b><br><span style="color:rgba(240,230,200,.4)">우측 [검사하기 →] 버튼을 눌러주세요. 검사 완료 시 점수와 분석이 자동 생성됩니다.</span>'
      : (sc.easy || sc.detail || sys.desc);
    var expertTxt = needsCheck
      ? '검사 후 전문 분석이 제공됩니다.'
      : (sc.expert || sc.detail || sys.desc);

    return '<div style="background:'+bg+';border:1px solid '+bdr+';border-radius:10px;padding:9px 11px;margin-bottom:4px">'
      // 헤더: 이름 + 점수 + (전문가 또는 검사하기) 버튼
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px">'
        +'<div style="display:flex;align-items:center;gap:5px">'
          +'<span style="font-size:14px;'+(needsCheck?'opacity:.5':'')+'">'+sys.emoji+'</span>'
          +'<span style="font-size:11px;font-weight:700;color:'+(needsCheck?'rgba(240,230,200,.6)':'var(--text-1)')+'">'+sys.name+'</span>'
          +(needsCheck?'<span style="font-size:8px;padding:1px 5px;background:rgba(248,113,113,.1);border:1px solid rgba(248,113,113,.25);border-radius:4px;color:rgba(252,165,165,.85);font-weight:700;margin-left:3px;">🔒 미검사</span>':'')
        +'</div>'
        +'<div style="display:flex;align-items:center;gap:5px">'
          +(needsCheck
            ? '<span style="font-family:Orbitron,sans-serif;font-size:12px;font-weight:700;color:rgba(148,163,184,.6)">0</span>'
              +'<button onclick="lottoGotoCheck(\''+checkKind+'\')" '
              +'style="font-size:9px;padding:2px 7px;border-radius:6px;background:rgba(212,168,67,.18);'
              +'border:1px solid rgba(212,168,67,.5);color:#d4a843;cursor:pointer;white-space:nowrap;'
              +'font-family:inherit;font-weight:800">검사하기 →</button>'
            : '<span style="font-family:Orbitron,sans-serif;font-size:12px;font-weight:700;color:'+col+'">'+bar+'</span>'
              +'<button id="'+cid+'_btn" data-cid="'+cid+'" onclick="toggle18Expert(this.dataset.cid)" '
              +'style="font-size:9px;padding:2px 6px;border-radius:6px;background:rgba(212,168,67,.12);'
              +'border:1px solid rgba(212,168,67,.3);color:var(--gold);cursor:pointer;white-space:nowrap;'
              +'font-family:inherit">전문가▾</button>')
        +'</div>'
      +'</div>'
      // 점수 바
      +'<div style="width:100%;height:3px;background:rgba(255,255,255,.07);border-radius:2px;margin-bottom:6px">'
        +'<div style="width:'+bar+'%;height:3px;background:'+col+';border-radius:2px;transition:width .8s"></div>'
      +'</div>'
      // 일반인 설명 (항상 표시)
      +'<div id="'+cid+'_easy" style="font-size:10px;color:var(--text-2);line-height:1.65">'+easyTxt+'</div>'
      // 전문가 분석 (토글)
      +'<div id="'+cid+'_exp" style="display:none;margin-top:6px;padding:7px 9px;'
        +'background:rgba(212,168,67,.05);border-left:2px solid rgba(212,168,67,.4);'
        +'border-radius:0 6px 6px 0">'
        +'<div style="font-size:9px;color:var(--gold);font-weight:700;margin-bottom:3px;letter-spacing:.05em">📚 전문가 분석</div>'
        +'<div style="font-size:10px;color:rgba(212,168,67,.85);line-height:1.7">'+expertTxt+'</div>'
      +'</div>'
      +(sc.advice && !needsCheck?'<div style="font-size:9px;color:'+col+';margin-top:4px;opacity:.8">→ '+sc.advice+'</div>':'')
      +'</div>';
  }

  var html = '<div style="margin:16px 0 8px;padding:14px;background:linear-gradient(135deg,rgba(212,168,67,.05),rgba(167,139,250,.03));border:1px solid rgba(212,168,67,.15);border-radius:14px">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:6px">'
      +'<div style="font-size:12px;font-weight:700;color:var(--gold);letter-spacing:.06em">'
        +_cgoTX('🌌 50대 역학 중 × NASA 실시간 분석','🌌 50 Systems × NASA Real-time Analysis')+nasaTag
      +'</div>'
      +'<div style="font-size:10px;color:var(--text-3)">각 카드 우측 <span style="color:var(--gold)">전문가▾</span> 클릭 시 전문 분석 열람</div>'
    +'</div>'
    + (context==='naming'
      ? ('<div style="font-size:10px;color:var(--gold);font-weight:700;margin-bottom:8px;padding:4px 10px;background:rgba(212,168,67,.08);border-radius:6px;letter-spacing:.05em">✍️ '+(typeof _cgoT==="function"?_cgoT('이름 핵심 역학'):'이름 핵심 역학')+'</div>'
        +_18SYSTEMS.filter(function(s){return _nmCore[s.id];}).map(function(sys){ return makeCard(sys, sys.group==='서'); }).join('')
        +'<button onclick="_nmToggleMore(this)" style="width:100%;margin-top:6px;padding:9px;background:rgba(212,168,67,.1);border:1px solid rgba(212,168,67,.3);border-radius:8px;color:var(--gold);font-size:11px;font-weight:700;cursor:pointer;font-family:inherit">'+(typeof _cgoT==="function"?_cgoT('🔍 더보기 — 나머지 역학 분석'):'🔍 더보기 — 나머지 역학 분석')+'</button>'
        +'<div id="nmMoreEng" style="display:none;margin-top:6px">'
        +_18SYSTEMS.filter(function(s){return !_nmCore[s.id] && s.id!=='kusei';}).map(function(sys){ return makeCard(sys, sys.group==='서'); }).join('')
        +'</div>')
      : ('<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'
      // 핵심 8선 (동양) — 카드 있을 때만
      +(function(){
        var _dc=_18SYSTEMS.filter(function(s){return s.group==='동'&&_lottoFilter(s);});
        if(!_dc.length) return '';
        return '<div>'
          +'<div style="font-size:10px;color:var(--gold);font-weight:700;margin-bottom:8px;'
          +'padding:4px 10px;background:rgba(212,168,67,.08);border-radius:6px;letter-spacing:.05em">'
          +_cgoTX('핵심 8선 — 우주·천문 직결','Core 8 Lines — Space Direct')+'</div>'
          +_dc.map(function(sys){ return makeCard(sys,false); }).join('')
          +'</div>';
      }())
      // West 5 / 서양5 — 카드 있을 때만
      +(function(){
        var _sc=_18SYSTEMS.filter(function(s){return s.group==='서'&&_lottoFilter(s);});
        if(!_sc.length) return '';
        return '<div>'
          +'<div style="font-size:10px;color:#a78bfa;font-weight:700;margin-bottom:8px;'
          +'padding:4px 10px;background:rgba(167,139,250,.08);border-radius:6px;letter-spacing:.05em">'
          +_cgoTX('⭐ 서양5 · 동양6 · 심리2','⭐ West 5 · East 6 · Psych 2')+'</div>'
          +_sc.map(function(sys){return makeCard(sys,true);}).join('')
          +'</div>';
      }())
    +'</div>'))
  +'</div>';
  return html;
}

// ══════════════════════════════════════════
// ✦ 행운 번호 정당성 막대 그래프 (D 혼합: 기여도60% + 구조적합도40%)
// ══════════════════════════════════════════
function _lottoBuildSysFitness(method, domOh, lifeNumVal, nums) {
  // ══════════════════════════════════════════
  // 파트너님 공식 14개 점수표 기반 (정직 원칙)
  // 🔴 핵심 4대 (95~88) — ILI 직접 계산
  // 🟡 보조 5대 (80~70) — 실제 사용
  // 🔵 부적 3대 (55~50) — 부적 프롬프트 전용
  // 🟤 바이오 2대 (55~45) — 바이오스캔 전용
  // ══════════════════════════════════════════

  // method 정규화 (3체계 처리)
  var baseMethod = method || 'all18';
  var hasNasa = false;
  var hasBio = false;
  if (baseMethod.indexOf('+bio') >= 0) {
    baseMethod = baseMethod.replace('+bio',''); hasNasa = true; hasBio = true;
  } else if (baseMethod.indexOf('+nasa') >= 0) {
    baseMethod = baseMethod.replace('+nasa',''); hasNasa = true;
  }
  if (baseMethod === 'nasa18') hasNasa = true;
  if (baseMethod === 'all18')  { hasNasa = true; hasBio = true; }

  // ── 14개 역학 베이스 점수 (파트너님 점수표 그대로) ──
  // 그룹 A: 핵심 4대 — ILI 직접 계산
  var baseScore = {
    saju:    {score:95, group:'A', emoji:'☯',  name:'사주명리',     short:(typeof _cgoT==='function'?_cgoT('ILI 직접 계산 + 30% 가중'):'ILI direct calc + 30% weighted')},
    jami:    {score:90, group:'A', emoji:'⭐', name:'자미두수',     short:(typeof _cgoT==='function'?_cgoT('ILI 직접 계산'):'ILI direct calculation')},
    astro:   {score:88, group:'A', emoji:'♈',  name:'서양 점성술',  short:(typeof _cgoT==='function'?_cgoT('ILI 직접 계산 + 15% 가중'):'ILI direct calc + 15% weighted')},
    num:     {score:92, group:'A', emoji:'🔢', name:'수비학',       short:(typeof _cgoT==='function'?_cgoT('ILI 직접 계산 + 20% 가중'):'ILI direct calc + 20% weighted')},
    // 그룹 B: 보조 5대 — 실제 계산 사용
    gmd:     {score:80, group:'B', emoji:'🧭', name:'기문둔갑',     short:(typeof _cgoT==='function'?_cgoT('나침반·건강 실제 계산'):'Compass·health actual calculation')},
    kusei:   {score:78, group:'B', emoji:'🌟', name:'구성기학',     short:(typeof _cgoT==='function'?_cgoT('프로필 + ILI 10% 가중'):'Profile + ILI 10% weighted')},
    juyeok:  {score:72, group:'B', emoji:'☱',  name:'주역',         short:(typeof _cgoT==='function'?_cgoT('건강리포트·괘 팝업'):'Health report·Hexagram popup')},
    seong:   {score:70, group:'B', emoji:'✍',  name:'성명학',       short:(typeof _cgoT==='function'?_cgoT('작명 페이지'):'Naming page')},
    tarot:   {score:75, group:'B', emoji:'🎴', name:'타로',         short:(typeof _cgoT==='function'?_cgoT('로또·아르카나 페이지'):'Lucky·Arcana page')},
    taeul:   {score:68, group:'B', emoji:'🌀', name:'태을신수',     short:(typeof _cgoT==='function'?_cgoT('시대 에너지 흐름'):'Era energy flow')},
    // 그룹 D: 바이오 전용 2대 — 바이오스캔만
    gwansang:{score:55, group:'D', emoji:'👁',  name:'관상학',       short:(typeof _cgoT==='function'?_cgoT('바이오스캔·건강'):'Bio scan·health')},
    pungsu:  {score:45, group:'D', emoji:'🌍', name:'풍수지리',     short:(typeof _cgoT==='function'?_cgoT('건강 리포트'):'Health report')}
  };

  // ── 가중치 적용 ──
  // 1) 선택된 method에 직접 사용된 역학은 기본 점수 (만점 가까이)
  // 2) 사용 안 된 역학은 -10점 패널티 (파트너님 점수표는 "역할" 기준이므로)
  // 3) NASA 통합 시: 점성술·자미두수 +5
  // 4) 생체 통합 시: 사주·수비 +3 (생체는 ILI에 직접 영향)

  var directUse = {
    saju:   ['saju','all18'],
    jami:   ['jami','all18'],
    astro:  ['astro','all18'],
    num:    ['num','all18'],
    gmd:    ['gmd','all18'],
    kusei:  ['kusei','num','gmd','all18','jami'],
    tarot:  ['tarot','all18'],
    taeul:  ['taeul','all18']
  };

  // 정직한 최종 점수 계산
  var sysList = Object.keys(baseScore).map(function(id){
    var s = baseScore[id];
    var sc = s.score;
    var direct = (directUse[id]||[]).indexOf(baseMethod) >= 0;

    // ✦ 정직 원칙: 미검사 역학 체크 (0점 + 회색 + 검사하기 →) ✦
    var notScanned = false;
    var checkKind = null;
    if (id === 'tarot' && !(window._qt && window._qt.selectedCard)) {
      notScanned = true; checkKind = 'tarot';
    } else if (id === 'gwansang' && !(window._bioSkinData && window._bioSkinData.face)) {
      notScanned = true; checkKind = 'face';
    }
    // (풍수지리·성명학 등은 검사 개념이 모호하므로 일단 점수 비례 처리)

    // 미검사면 0점 + direct false 강제
    if (notScanned) {
      sc = 0;
      direct = false;
    } else {
      // 직접 사용 안 된 역학은 ÷2 (정직)
      if (!direct && s.group !== 'D') {
        sc = Math.round(sc * 0.55);
      }
      // 그룹 D(생체·rPPG)는 번호 산출에 직접 사용 X — 항상 절반
      if (s.group === 'D') {
        sc = Math.round(sc * 0.5);
      }
      // NASA 통합 보정
      if (hasNasa && (id === 'astro' || id === 'jami')) sc = Math.min(s.score, sc + 8);
      // 생체 통합 보정
      if (hasBio && (id === 'saju' || id === 'num')) sc = Math.min(s.score, sc + 5);
      // 선택된 역학 자체는 만점 근처로
      if (direct) sc = Math.min(85, sc); // ⭐ 최대 85점 — 정직 원칙
    }

    return {id:id, score:sc, baseScore:s.score, direct:direct, group:s.group, emoji:s.emoji, name:s.name, short:s.short, notScanned:notScanned, checkKind:checkKind};
  });

  // 그룹별 분류
  var groups = {A:[], B:[], D:[]};
  sysList.forEach(function(s){ groups[s.group].push(s); });
  // 각 그룹 내 점수순 정렬
  ['A','B','D'].forEach(function(g){
    groups[g].sort(function(a,b){return b.score-a.score;});
  });

  // ── method 라벨 ──
  var sysLabel = ({
    saju:'☯️ 사주명리', jami:'🌟 자미두수', astro:'♈ 서양 점성술',
    num:'🔢 수비학', gmd:'🧭 기문둔갑', kusei:'🌟 구성기학',
    tarot:'🎴 타로', kabala:'✡️ 카발라', taeul:'🌀 태을신수',
    nasa18:'🛰️ NASA 통합', all18:'✨ 9대 + NASA + 생체'
  })[baseMethod] || baseMethod;

  var sysExtra = (hasBio ? _cgoTX(' + 🧬 생체 (rPPG)',' + 🧬 Bio (rPPG)') : (hasNasa ? ' + 🛰️ NASA' : ''));
  if (baseMethod === 'all18' || baseMethod === 'nasa18') sysExtra = '';

  // ── HTML 빌드 ──
  var html =
    '<div style="margin:18px 0 14px;padding:18px 16px;background:#ffffff;border:1px solid rgba(212,168,67,.25);border-radius:16px;">'+
      '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;flex-wrap:wrap;gap:6px;">'+
        '<div style="font-size:13px;font-weight:900;color:#b8860b;letter-spacing:.06em;">'+_cgoTX('📊 역학 정당성 분석','📊 Metaphysics validity analysis')+'</div>'+''+
        '<div style="font-size:10px;color:rgba(139,107,11,.55);">'+_cgoTX('현재: ','Current: ')+(typeof _cgoT==='function'?_cgoT(sysLabel):sysLabel)+sysExtra+'</div>'+
        '<div style="font-size:9.5px;color:rgba(139,107,11,.72);line-height:1.6;margin-top:5px;padding:6px 9px;background:rgba(184,134,11,.06);border-radius:7px;">'+_cgoTX('선택한 <b>주력 역학</b>으로 번호를 뽑고, 번호와 연관된 <b>역학</b>이 그 정당성을 교차검증해요 — 점수가 높을수록 공명이 강합니다.','Numbers are drawn from your <b>selected primary system</b>, then the <b>number-related metaphysics</b> cross-validate their legitimacy — a higher score means stronger resonance.')+'</div>'+
      '</div>'+

      // 4그룹 안내 박스 (파트너님 요청)
      '<div style="margin-bottom:14px;padding:12px 14px;background:#f1f5f9;border:1px solid rgba(212,168,67,.18);border-radius:10px;">'+
        '<div style="font-size:10px;color:rgba(51,65,85,.55);line-height:1.85;margin-bottom:8px;">'+
          '💡 <b style="color:#b8860b">'+_cgoTX('정직 점수표:','Honest score table:')+'</b> '+_cgoTX('번호와 연관된 역학만 단계별로 보여드려요 — 선택한 역학은 상위 점수, 나머지는 교차검증이에요.','Only number-related metaphysics are shown, grouped by tier — your selected system scores near the top, the rest cross-check.')+''+
        '</div>'+
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:10px;line-height:1.6;">'+
          '<div style="padding:6px 8px;background:rgba(248,113,113,.05);border-left:2px solid #f87171;border-radius:0 5px 5px 0;"><b style="color:#dc2626">🔴 핵심 4대</b> <span style="color:rgba(51,65,85,.5)">— ILI 직접 (88~95)</span></div>'+
          '<div style="padding:6px 8px;background:rgba(251,191,36,.05);border-left:2px solid #fbbf24;border-radius:0 5px 5px 0;"><b style="color:#b45309">🟡 보조 역학</b> <span style="color:rgba(51,65,85,.5)">— 실제 사용</span></div>'+
          
          '<div style="padding:6px 8px;background:rgba(167,139,250,.05);border-left:2px solid #a78bfa;border-radius:0 5px 5px 0;"><b style="color:#6d28d9">🟤 생체 (rPPG)</b> <span style="color:rgba(51,65,85,.5)">— 3단계 전용</span></div>'+
        '</div>'+
      '</div>';

  // 그룹별 막대 출력
  var _kEN = (window._LANG&&window._LANG!=='ko');
  var groupHeaders = {
    A: {color:'#f87171', label:_kEN?'🔴 Core 4 — direct ILI calculation':'🔴 핵심 4대 — ILI 직접 계산'},
    B: {color:'#fbbf24', label:_kEN?'🟡 Auxiliary — actual calculation':'🟡 보조 역학 — 실제 계산'},
    D: {color:'#a78bfa', label:_kEN?'🟤 Bio (rPPG) — Tier 3 only':'🟤 생체 역학 (rPPG) — 3단계 전용'}
  };

  ['A','B','D'].forEach(function(g){
    if(g==='D' && !hasBio) return; // 생체(rPPG) 역학은 3단계에서만
    var hdr = groupHeaders[g];
    html +=
      '<div style="margin-top:14px;margin-bottom:8px;padding:6px 10px;background:#f1f5f9;border-left:3px solid '+hdr.color+';border-radius:0 6px 6px 0;">'+
        '<div style="font-size:11px;font-weight:800;color:'+hdr.color+';letter-spacing:.04em;">'+hdr.label+'</div>'+
      '</div>';

    groups[g].forEach(function(f){
      var sc = f.score;
      // ✦ 미검사 시 회색 처리 ✦
      var col = f.notScanned
        ? 'rgba(148,163,184,.6)'
        : (sc>=85?'#d4a843':sc>=70?'#34d399':sc>=55?'#60a5fa':sc>=40?'#a78bfa':'rgba(248,113,113,.7)');
      // 미검사면 [선택] 배지 절대 안 보이게, 대신 [🔒 미검사] 라벨
      var labelBadge = f.notScanned
        ? '<span style="display:inline-block;font-size:8px;padding:1px 5px;background:rgba(248,113,113,.1);border:1px solid rgba(248,113,113,.25);border-radius:4px;color:rgba(252,165,165,.85);font-weight:700;margin-left:4px;">🔒 미검사</span>'
        : (f.direct ? '<span style="display:inline-block;font-size:8px;padding:1px 5px;background:rgba(52,211,153,.15);border:1px solid rgba(52,211,153,.4);border-radius:4px;color:#34d399;font-weight:700;margin-left:4px;">선택</span>' : '');
      // 우측 점수 자리: 미검사면 0 + 검사하기 버튼, 정상이면 점수만
      var rightCell = f.notScanned
        ? '<button onclick="lottoGotoCheck(\''+f.checkKind+'\')" style="font-size:9px;padding:3px 7px;border-radius:6px;background:rgba(212,168,67,.15);border:1px solid rgba(212,168,67,.45);color:#b8860b;cursor:pointer;font-family:inherit;font-weight:800;white-space:nowrap;">검사 →</button>'
        : '<div style="font-family:Orbitron,sans-serif;font-size:13px;font-weight:900;color:'+col+';text-align:right;">'+sc+'</div>';
      // 우측 셀 너비: 미검사는 버튼이라 더 넓게
      var gridCols = f.notScanned ? '24px 1fr 56px' : '24px 1fr 36px';

      html +=
        '<div style="display:grid;grid-template-columns:'+gridCols+';gap:10px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.04);'+(f.notScanned?'opacity:.7;':'')+'">'+
          '<div style="font-size:16px;text-align:center;'+(f.notScanned?'opacity:.6;':'')+'">'+f.emoji+'</div>'+
          '<div>'+
            '<div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:4px;flex-wrap:wrap;gap:4px;">'+
              '<div style="font-size:11px;color:rgba(51,65,85,.85);font-weight:700;">'+f.name+labelBadge+'</div>'+
              '<div style="font-size:9px;color:rgba(51,65,85,.4);">'+f.short+'</div>'+
            '</div>'+
            '<div style="height:6px;background:rgba(255,255,255,.05);border-radius:3px;overflow:hidden;">'+
              '<div style="height:100%;width:'+sc+'%;background:linear-gradient(90deg,'+col+',rgba(212,168,67,.3));border-radius:3px;transition:width .8s ease-out;"></div>'+
            '</div>'+
          '</div>'+
          rightCell+
        '</div>';
    });
  });

  html += '</div>';

  // ══════════════════════════════════════════
  // ✦ 더 정확한 분석을 위한 검사 권유 (미검사 4종만 표시)
  // ✦ 타로 · 관상 · 손금 · NBTI
  // ══════════════════════════════════════════
  var checkItems = [];
  // 타로
  if (!(window._qt && window._qt.selectedCard)) {
    checkItems.push({
      kind:'tarot', emoji:'🎴', name:'아르카나 카드',
      desc:'Draw 1 of 78 cards intuitively — the message is added to your number analysis.',
      color:'#d4a843', bgCol:'rgba(212,168,67,.06)', brCol:'rgba(212,168,67,.3)'
    });
  }
  // 관상
  if (!(window._bioSkinData && window._bioSkinData.face)) {
    checkItems.push({
      kind:'face', emoji:'👁', name:'관상 스캔',
      desc:'33-second face scan — 12 facial zones + real-time fortune energy for +30% number accuracy.',
      color:'#a78bfa', bgCol:'rgba(167,139,250,.06)', brCol:'rgba(167,139,250,.3)'
    });
  }
  // 손금
  if (!(window._bioSkinData && window._bioSkinData.palm)) {
    checkItems.push({
      kind:'palm', emoji:'🤚', name:'손금 스캔',
      desc:'Both palms analyzed — life line + destiny line reflected in your lucky numbers.',
      color:'#fca5a5', bgCol:'rgba(252,165,165,.06)', brCol:'rgba(252,165,165,.3)'
    });
  }
  // NBTI
  if (!(window._mspResult && window._mspResult.type)) {
    checkItems.push({
      kind:'msp', emoji:'🧠', name:'CGO 인간유형 검사',
      desc:'16-type personality + Five Elements fusion test — personality patterns added to number flow.',
      color:'#c4b5fd', bgCol:'rgba(196,181,253,.06)', brCol:'rgba(196,181,253,.3)'
    });
  }

  if (checkItems.length > 0) {
    html += '<div style="margin:14px 0 0;padding:16px;background:#ffffff;border:1px dashed rgba(212,168,67,.3);border-radius:14px;">'+
      '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">'+
        '<span style="font-size:14px;">💎</span>'+
        '<div style="font-size:12px;font-weight:800;color:#b8860b;letter-spacing:.04em;">더 정확한 분석을 원하시나요?</div>'+
      '</div>'+
      '<div style="font-size:10px;color:rgba(51,65,85,.5);line-height:1.7;margin-bottom:12px;">'+
        'Add any of the tests below — bar-graph scores and number accuracy both rise from your next draw. Click only what you want.'+
      '</div>'+
      '<div style="display:flex;flex-direction:column;gap:8px;">';

    checkItems.forEach(function(item){
      html += '<div onclick="lottoGotoCheck(\''+item.kind+'\')" '+
        'style="display:flex;align-items:center;gap:12px;padding:11px 14px;background:'+item.bgCol+';border:1px solid '+item.brCol+';border-radius:11px;cursor:pointer;transition:all .2s;" '+
        'onmouseover="this.style.borderColor=\''+item.color+'\';this.style.transform=\'translateX(2px)\';" '+
        'onmouseout="this.style.borderColor=\''+item.brCol+'\';this.style.transform=\'\';">'+
        '<div style="font-size:22px;flex-shrink:0;">'+item.emoji+'</div>'+
        '<div style="flex:1;min-width:0;">'+
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;">'+
            '<span style="font-size:9px;padding:1px 6px;background:rgba(248,113,113,.12);border:1px solid rgba(248,113,113,.3);border-radius:4px;color:#fca5a5;font-weight:700;">🔒 미검사</span>'+
            '<span style="font-size:12px;font-weight:800;color:'+item.color+';">'+item.name+'</span>'+
          '</div>'+
          '<div style="font-size:10px;color:rgba(51,65,85,.55);line-height:1.65;">'+item.desc+'</div>'+
        '</div>'+
        '<div style="font-size:13px;color:'+item.color+';font-weight:800;flex-shrink:0;">검사 →</div>'+
      '</div>';
    });

    html += '</div></div>';
  }

  return html;
}

