function getSuri(n) {
  if(n > 81) n = ((n-1)%81)+1;
  return SURI_81[n] || {name:'보통수',luck:'보통',desc:'평범한 수. 노력으로 극복 가능'};
}

// 오행 보완 관계 (어떤 오행을 보완해야 하는지)
var OH_SUPPLEMENT = {목:'화',화:'토',토:'금',금:'수',수:'목'};
// 오행 상생
var OH_GENERATE = {목:'화',화:'토',토:'금',금:'수',수:'목'};

function getHanjaStroke(hj) {
  // 주요 한자 획수 (실제 한자 획수 근사값)
  var strokeMap = {
    金:8,李:7,朴:6,崔:11,鄭:14,姜:9,趙:14,尹:4,張:11,林:8,
    韓:17,吳:7,徐:10,申:5,權:15,黃:12,安:6,宋:7,柳:9,全:6
  };
  return strokeMap[hj] || 8;
}

function calcTotalStroke(surnameHj, char1Hj, char2Hj) {
  var s = getHanjaStroke(surnameHj);
  var c1 = char1Hj.stroke || 8;
  var c2 = char2Hj ? (char2Hj.stroke || 8) : 0;
  return {
    wonGuk: s + c1,           // 원격 (성+이름첫째)
    hyeongGuk: c1 + (c2||0), // 형격 (이름 합계)
    iGuk: s + c1 + (c2||0),  // 이격 (전체)
    jongGuk: s + (c2||c1)    // 종격 (성+이름끝)
  };
}

function scoreHanja(surname, ohTarget, ohSupplement, char1, char2) {
  var score = 60;
  // 오행 매칭 보너스
  if(char1.oh === ohTarget) score += 15;
  if(char1.oh === ohSupplement) score += 10;
  if(char2 && char2.oh === ohTarget) score += 15;
  if(char2 && char2.oh === ohSupplement) score += 10;
  // 획수 운수
  var strokes = calcTotalStroke(
    {stroke: getHanjaStroke(SURNAME_HANJA[surname]||'金')},
    char1, char2
  );
  var suri = getSuri(strokes.iGuk);
  if(suri.luck==='대길') score += 12;
  else if(suri.luck==='길') score += 6;
  else if(suri.luck==='흉') score -= 10;
  return Math.min(99, Math.max(40, score));
}

function namingSeed(surname, birthY, birthM, birthD, gender) {
  var s = (surname.charCodeAt(0)||50)*7 + birthY*13 + birthM*31 + birthD*5 + (gender==='M'?3:7);
  s = (s*1103515245+12345)&0x7fffffff;
  return s;
}
function nmRng(s){ return ((s*1103515245+12345)&0x7fffffff); }

function selectSurname(sn) {
  if(window.cgoPickSurname){
    /* ★C-68: 한글 성씨로 불려도 칩의 한자를 찾아 넣는다 */
    var hj=sn;
    try{
      var c=document.querySelector('#surnameChips .surname-chip[data-sn="'+sn+'"]');
      if(c && c.getAttribute('data-hj')) hj=c.getAttribute('data-hj');
    }catch(e){}
    window.cgoPickSurname(hj, sn); return;
  }
  var f=document.getElementById('nmSurname');
  if(f){ f.value = sn; try{ f.dispatchEvent(new Event('input',{bubbles:true})); }catch(e){} }
  document.querySelectorAll('#surnameChips .surname-chip').forEach(function(c){
    var d=c.getAttribute('data-sn');
    c.classList.toggle('active', d ? (d===sn) : c.textContent.indexOf(sn)===0);
  });
}
try{ window.selectSurname = selectSurname; }catch(e){}   /* ★C-68 전역 노출 */

