function gmdSeed(y,m,d,bYear,lifeNum){
  var s=(y*397+m*41+d*13+bYear*7+(lifeNum||5)*17)%9999;
  s=(s*1103515245+12345)&0x7fffffff;
  return s;
}
function gmdRng(s){return ((s*1103515245+12345)&0x7fffffff);}

function generateGMD(r){
  var today=window._fcBase||new Date();
  var ty=today.getFullYear(),tm=today.getMonth()+1,td=today.getDate();
  var wds=['일','월','화','수','목','금','토'];
  var wd=wds[today.getDay()];

  // CGO-MASTER CEI 기반 에너지 보정
  var M=window._CGO_MASTER;
  var _gmdCEI = M ? (M.cei||M.ili||70) : (r.ili||70);
  var _gmdBioBonus = (M&&M.bio.scanned) ? Math.round((M.bio.fci||0)*0.05) : 0;

  var seed=gmdSeed(ty,tm,td,r.y,r.lifeNum);

  // 방위별 에너지 계산 (8방위) — CEI 기반 보정
  var dirEnergies=GMD_DIRS.map(function(dir,i){
    seed=gmdRng(seed);
    var base=40+(seed%50);
    var bonus=0;
    var ohDir={목:[2,3],화:[3,4],토:[0,4],금:[6,7],수:[0,1]};
    if(ohDir[r.domOh] && ohDir[r.domOh].indexOf(i)>=0) bonus=15;
    // CEI 높을수록 전체 에너지 상향
    var ceiBonus = Math.round((_gmdCEI-70)*0.15) + _gmdBioBonus;
    var energy=Math.min(98,Math.max(35,base+bonus+ceiBonus));
    return {dir:dir.dir,en:dir.en,deg:dir.deg,emoji:dir.emoji,chi:dir.chi,energy:energy};
  });

  // 에너지 정렬
  var sorted=[].concat(dirEnergies).sort(function(a,b){return b.energy-a.energy;});
  var best=sorted[0], second=sorted[1], third=sorted[2];
  var worst=sorted[7], bad2=sorted[6];

  // 귀인 선택
  seed=gmdRng(seed);
  var guiinIdx=seed%12;
  var guiin=GMD_GUIINS[guiinIdx];

  // 귀인 방위 (최상 방위와 연결)
  var guiinDir=best;

  // 오늘의 문(門)
  seed=gmdRng(seed);
  var gateIdx=seed%8;
  var todayGate=GMD_GATES[gateIdx];
  var gateDesc=GMD_GATE_DESC[todayGate];

  // 오늘의 성(星)
  seed=gmdRng(seed);
  var starIdx=seed%9;
  var todayStar=GMD_STARS[starIdx];

  // 시간별 에너지 (12시진)
  var shigans=['子(23-1시)','丑(1-3시)','寅(3-5시)','卯(5-7시)','辰(7-9시)','巳(9-11시)','午(11-13시)','未(13-15시)','申(15-17시)','酉(17-19시)','戌(19-21시)','亥(21-23시)'];
  var timeEnergies=shigans.map(function(sh){
    seed=gmdRng(seed);
    return {label:sh,energy:35+(seed%55)};
  });

  // 나침반 SVG 생성
  var cx=140,cy=140,r2=120,r3=90,r4=60;
  var compassSvg=buildCompassSvg(dirEnergies,best,cx,cy,r2,r3,r4);

  // 방위 카드 렌더링 (3x3 그리드, 중앙은 본인)
  // NW N NE / W 本 E / SW S SE 순서
  var gridOrder=['북서','북','북동','서','中','동','남서','남','동남'];
  var dirMap={};
  dirEnergies.forEach(function(d){dirMap[d.dir]=d;});

  var dirCardHtml=gridOrder.map(function(dk){
    if(dk==='中'){
      return '<div class="dir-card" style="background:rgba(212,168,67,0.1);border-color:rgba(212,168,67,0.4)">'+
        '<div style="font-size:10px;color:var(--gold);margin-bottom:2px">本</div>'+
        '<div style="font-size:18px">'+r.zodiacName.charAt(0)+'</div>'+
        '<div style="font-size:9px;color:var(--text-3)">'+r.name+'</div>'+
        '</div>';
    }
    var d=dirMap[dk];
    if(!d) return '<div class="dir-card"></div>';
    var luckClass=d===best?'luck-1':d===second?'luck-2':d===third?'luck-3':d===worst?'bad-1':d===bad2?'bad-2':'';
    var luckLabel=d===best?'🥇 최상':d===second?'🥈 길':d===third?'🥉 보통':d===worst?'⛔ 흉':d===bad2?'⚠ 주의':'— 평';
    var luckColor=d===best?'var(--gold)':d===second?'var(--green)':d===third?'var(--cyan)':d===worst?'var(--red)':'var(--text-3)';
    return '<div class="dir-card '+luckClass+'" onclick="gmdDirPop('+JSON.stringify(d)+','+JSON.stringify(luckLabel)+')" style="cursor:pointer">'+
      '<div class="dir-card-dir" style="color:'+luckColor+'">'+d.chi+'<span style="font-size:9px;color:rgba(240,230,200,0.85);">('+_chiKr(d.chi)+')</span></div>'+
      '<div class="dir-card-name">'+d.dir+' ('+d.en+')</div>'+
      '<div class="dir-card-label" style="color:'+luckColor+'">'+luckLabel+'</div>'+
      '<div class="dir-card-desc">'+d.energy+'%</div>'+
      '</div>';
  }).join('');

  // 시간별 에너지 바 (현재 시간 하이라이트)
  var nowHour=today.getHours();
  var timeHtml=timeEnergies.map(function(t,i){
    var isNow=(nowHour>=i*2 && nowHour<(i+1)*2);
    var barColor=t.energy>=75?'var(--gold)':t.energy>=60?'var(--green)':'var(--text-3)';
    return '<div class="time-bar-row" style="'+(isNow?'background:rgba(212,168,67,0.06);border-radius:6px;padding:2px 4px;':'')+'">'+
      '<div class="time-bar-label" style="'+(isNow?'color:var(--gold);font-weight:600':'')+'">'+t.label.split('(')[0]+'</div>'+
      '<div class="time-bar-track"><div class="time-bar-fill" style="width:0%;background:'+barColor+'" data-w="'+t.energy+'"></div></div>'+
      '<div class="time-bar-val">'+t.energy+'</div>'+
      '</div>';
  }).join('');

  // 최종 HTML 조립
  var html=
  '<div class="gmd-layout">'+

  // 왼쪽: 나침반 + 방위 그리드
  '<div class="gmd-left">'+
  '<div class="compass-wrap">'+
  '<div class="compass-title">🧭 오늘의 방위 에너지 · '+ty+'년 '+tm+'월 '+td+'일 ('+wd+'요일)</div>'+
  compassSvg+
  '<div class="dir-grid">'+dirCardHtml+'</div>'+
  '</div>'+

  // 귀인 패널
  '<div class="gui-panel" onclick="gmdGuiinPop(event)" id="gmdGuiinPanel" style="cursor:pointer;transition:border-color .2s">'+
  '<div class="gui-title">👑 오늘의 귀인 (貴人) <span style="font-size:9px;color:rgba(212,168,67,.4);margin-left:auto">▶ 상세 방위·인물 분석</span></div>'+
  '<div class="gui-main">'+
  '<div class="gui-icon">'+guiin.icon+'</div>'+
  '<div>'+
  '<div class="gui-name">'+guiin.name+' <span style="font-size:13px;font-family:Noto Sans KR">'+guiin.kr+'</span></div>'+
  '<div class="gui-sub">'+guiin.desc+'</div>'+
  '</div></div>'+
  '<div class="gui-tags">'+
  '<span class="gui-tag">'+guiinDir.dir+' 방향</span>'+
  '<span class="gui-tag">'+guiinDir.chi+'('+_chiKr(guiinDir.chi)+') 궁</span>'+
  '<span class="gui-tag">'+(typeof _cgoT==='function'?_cgoT('에너지'):'에너지')+' '+guiinDir.energy+'%</span>'+
  '</div></div>'+
  '</div>'+

  // 오른쪽: 분석 + 시간별
  '<div class="gmd-right">'+

  // 오늘의 기문 분석
  '<div class="gmd-analysis">'+
  '<div class="gmd-analysis-title">'+((typeof _cgoT==='function')?_cgoT('⚡ 오늘의 기문 분석 — {name}님'):'⚡ 오늘의 기문 분석 — {name}님').replace('{name}',r.name)+'</div>'+
  '<div class="gmd-row"><span class="gmd-row-label">☯ 일간 (日干)</span><span class="gmd-row-val">'+r.dGJ.gan+r.dGJ.ji+' ('+ganToOhaeng(r.dGJ.gan)+')</span></div>'+
  '<div class="gmd-row"><span class="gmd-row-label">🚪 오늘의 문 (門)</span><span class="gmd-row-val">'+todayGate+'</span></div>'+
  '<div class="gmd-row"><span class="gmd-row-label">✨ 오늘의 성 (星)</span><span class="gmd-row-val">'+todayStar+'</span></div>'+
  '<div class="gmd-row"><span class="gmd-row-label">🧭 최길 방위</span><span class="gmd-row-val" style="color:var(--gold)">'+best.dir+' ('+best.chi+') '+best.energy+'%</span></div>'+
  '<div class="gmd-row"><span class="gmd-row-label">⛔ 주의 방위</span><span class="gmd-row-val" style="color:var(--red)">'+worst.dir+' ('+worst.chi+') '+worst.energy+'%</span></div>'+
  '<div style="margin-top:12px;padding:12px;background:rgba(212,168,67,0.06);border:1px solid rgba(212,168,67,0.2);border-radius:8px;font-size:12px;color:var(--text-2);line-height:1.8">'+
  '<strong style="color:var(--gold)">'+todayGate+' 해석</strong><br>'+gateDesc+
  '</div></div>'+

  // 시간별 에너지 — 클릭형 (18대 역학 팝업)
  (function(){
    var _sOh =['수','토','목','목','토','화','화','토','금','금','토','수'];
    var _sEmo=['🌑','🌒','🐅','🌅','☀️','🌤','🌞','🌻','🌆','🌇','🌃','🌙'];
    var _sNm =['자시','축시','인시','묘시','진시','사시','오시','미시','신시','유시','술시','해시'];
    var _nowH=today.getHours();
    var _ss={목:'화',화:'토',토:'금',금:'수',수:'목'};
    var _sk={목:'토',화:'금',토:'수',금:'목',수:'화'};
    var _myOh=r.domOh||'토';
    var _fseed=seed;
    var _rows=_sNm.map(function(nm,i){
      _fseed=rng(_fseed);
      var _en=35+(_fseed%55);
      var _isNow=(i===0)?(_nowH===23||_nowH===0):(_nowH>=(i*2)&&_nowH<((i+1)*2));
      var _boost=_ss[_sOh[i]]===_myOh||_sOh[i]===_myOh;
      var _warn=_sk[_sOh[i]]===_myOh;
      var _bc=_boost?'#34d399':_warn?'#f87171':_en>=75?'var(--gold)':'var(--text-3)';
      var _bg=_isNow?'background:rgba(212,168,67,.1);border:1px solid rgba(212,168,67,.35);border-radius:10px;padding:5px 8px;'
             :_boost?'background:rgba(52,211,153,.05);border-radius:8px;padding:3px 6px;'
             :_warn?'background:rgba(248,113,113,.05);border-radius:8px;padding:3px 6px;'
             :'padding:2px 4px;';
      return '<div class="time-bar-row" onclick="showSijinDetail('+i+','+_en+')" style="cursor:pointer;'+_bg+'">'+
        '<div class="time-bar-label" style="'+(_isNow?'color:#d4a843;font-weight:700;':_boost?'color:#34d399;':_warn?'color:#f87171;':'')+'">'+((_isNow)?'▶ ':'')+_sEmo[i]+' '+nm+'<span style="font-size:9px;opacity:.6">'+(_boost?' ⭐':_warn?' ⚠':'')+'</span></div>'+
        '<div class="time-bar-track"><div class="time-bar-fill" style="width:0%;background:'+_bc+'" data-w="'+_en+'"></div></div>'+
        '<div class="time-bar-val" style="color:'+_bc+';font-size:10px">'+_en+' <span style="font-size:8px;opacity:.5">▸</span></div>'+
      '</div>';
    }).join('');
    return '<div class="time-energy">'+
      '<div class="time-energy-title">⏰ 시진별 운세 (탭하면 50대 역학 중×성씨 상세분석 ▸) '+
      '<span style="font-size:9px;background:rgba(212,168,67,.12);padding:2px 7px;border-radius:8px;color:rgba(212,168,67,.8)">⭐상생 ⚠상극</span></div>'+
      '<div class="time-bars">'+_rows+'</div>'+
    '</div>';
  })()+

  // 행운 총정리
  '<div class="luck-summary">'+
  '<div class="luck-summary-title">🍀 오늘의 행운 총정리</div>'+
  '<div class="luck-items">'+
  '<div class="luck-item"><div class="luck-item-label">🧭 최길 방위</div><div class="luck-item-val" style="color:var(--gold)">'+best.dir+' ('+best.chi+')</div></div>'+
  '<div class="luck-item"><div class="luck-item-label">👑 오늘의 귀인</div><div class="luck-item-val" style="color:var(--amber)">'+guiin.icon+' '+guiin.kr+'</div></div>'+
  '<div class="luck-item"><div class="luck-item-label">🚪 오늘의 문</div><div class="luck-item-val" style="color:var(--cyan)">'+todayGate+'</div></div>'+
  '<div class="luck-item"><div class="luck-item-label">✨ 오늘의 성</div><div class="luck-item-val" style="color:var(--green)">'+todayStar.substring(0,3)+'</div></div>'+
  '<div class="luck-item"><div class="luck-item-label">⬆ 출행 방향</div><div class="luck-item-val" style="color:var(--gold)">'+best.dir+' '+best.emoji+'</div></div>'+
  '<div class="luck-item"><div class="luck-item-label">⛔ 피할 방위</div><div class="luck-item-val" style="color:var(--red)">'+worst.dir+' '+worst.emoji+'</div></div>'+
  '</div></div>'+

  '<button class="gmd-refresh-btn" onclick="generateGMD(window._gmdResult||{})">🔄 오늘 다시 분석</button>'+

  '</div></div>'; // gmd-right, gmd-layout

  var c=document.getElementById('gmdContent');
  if(c){
    c.innerHTML=html;
    // 시간별 에너지 바 애니메이션
    setTimeout(function(){
      c.querySelectorAll('.time-bar-fill[data-w]').forEach(function(b){
        b.style.width=b.getAttribute('data-w')+'%';
      });
    },200);
    // 결과 저장 (재분석용)
    window._gmdResult=r;
    window._gmdDone = true;
    // 귀인 데이터 저장
    window._gmdGuiin={guiin:guiin,guiinDir:guiinDir,ty:ty,tm:tm,td:td,wd:wd,best:best,dirEnergies:dirEnergies};
  }
}

function buildCompassSvg(dirs,best,cx,cy,rOuter,rMid,rInner){
  var size=cx*2;
  var parts=[];

  // 배경 원들
  parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="'+rOuter+'" fill="rgba(99,130,201,0.04)" stroke="rgba(99,130,201,0.2)" stroke-width="1"/>');
  parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="'+rMid+'" fill="rgba(212,168,67,0.03)" stroke="rgba(212,168,67,0.15)" stroke-width="1"/>');
  parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="'+rInner+'" fill="rgba(212,168,67,0.05)" stroke="rgba(212,168,67,0.25)" stroke-width="1.5"/>');

  // 십자선
  ['0','90','45','135'].forEach(function(degStr){
    var deg=parseInt(degStr)*Math.PI/180;
    var x1=cx+Math.sin(deg)*(rOuter+10);
    var y1=cy-Math.cos(deg)*(rOuter+10);
    var x2=cx-Math.sin(deg)*(rOuter+10);
    var y2=cy+Math.cos(deg)*(rOuter+10);
    parts.push('<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="rgba(99,130,201,0.15)" stroke-width="0.5" stroke-dasharray="3,3"/>');
  });

  // 방위별 에너지 섹터 + 라벨
  dirs.forEach(function(d,i){
    var deg=(d.deg-90)*Math.PI/180;
    var nextDeg=((d.deg+45-90)*Math.PI/180);
    var prevDeg=((d.deg-45-90)*Math.PI/180);

    // 섹터 (파이 슬라이스)
    var isBest=(d===best);
    var alpha=d.energy/100*0.4+0.05;
    var fill=isBest?'rgba(212,168,67,'+alpha+')':'rgba(99,130,201,'+(alpha*0.6)+')';
    var strokeC=isBest?'rgba(212,168,67,0.6)':'rgba(99,130,201,0.2)';
    var r5=rOuter*d.energy/100;

    var midDeg=deg;
    var x1=cx+Math.cos(prevDeg)*rInner, y1=cy+Math.sin(prevDeg)*rInner;
    var x2=cx+Math.cos(prevDeg)*r5, y2=cy+Math.sin(prevDeg)*r5;
    var x3=cx+Math.cos(nextDeg)*r5, y3=cy+Math.sin(nextDeg)*r5;
    var x4=cx+Math.cos(nextDeg)*rInner, y4=cy+Math.sin(nextDeg)*rInner;
    parts.push('<path d="M'+x1+','+y1+' L'+x2+','+y2+' A'+r5+','+r5+' 0 0,1 '+x3+','+y3+' L'+x4+','+y4+' A'+rInner+','+rInner+' 0 0,0 '+x1+','+y1+'Z" fill="'+fill+'" stroke="'+strokeC+'" stroke-width="0.5"/>');

    // 방위 라벨
    var labelR=rOuter+18;
    var lx=cx+Math.cos(midDeg)*labelR;
    var ly=cy+Math.sin(midDeg)*labelR;
    var labelColor=isBest?'#d4a843':'#94a3b8';
    var fw=isBest?'700':'400';
    parts.push('<text x="'+lx+'" y="'+(ly+4)+'" text-anchor="middle" font-size="'+(isBest?'13':'11')+'" fill="'+labelColor+'" font-weight="'+fw+'" font-family="Noto Serif KR,serif">'+d.chi+'</text>');

    // 방위 한글
    var kr2R=rOuter+32;
    var kx=cx+Math.cos(midDeg)*kr2R;
    var ky=cy+Math.sin(midDeg)*kr2R;
    parts.push('<text x="'+kx+'" y="'+(ky+3)+'" text-anchor="middle" font-size="9" fill="'+labelColor+'" font-family="Noto Sans KR,sans-serif">'+d.dir+'</text>');
  });

  // 중앙 원 + 태극 심볼
  parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="28" fill="rgba(13,21,38,0.9)" stroke="rgba(212,168,67,0.4)" stroke-width="1.5"/>');
  parts.push('<text x="'+cx+'" y="'+(cy+8)+'" text-anchor="middle" font-size="22" fill="#d4a843">☯</text>');

  // 나침반 바늘 (최길 방위 → 금색)
  var bestDeg=(best.deg-90)*Math.PI/180;
  var nTipX=cx+Math.cos(bestDeg)*55;
  var nTipY=cy+Math.sin(bestDeg)*55;
  var nTailX=cx-Math.cos(bestDeg)*30;
  var nTailY=cy-Math.sin(bestDeg)*30;
  // 바늘 좌우 날개
  var perpDeg=bestDeg+Math.PI/2;
  var wingW=7;
  var wx1=cx+Math.cos(perpDeg)*wingW;
  var wy1=cy+Math.sin(perpDeg)*wingW;
  var wx2=cx-Math.cos(perpDeg)*wingW;
  var wy2=cy-Math.sin(perpDeg)*wingW;
  parts.push('<polygon points="'+nTipX+','+nTipY+' '+wx1+','+wy1+' '+nTailX+','+nTailY+' '+wx2+','+wy2+'" fill="url(#needleGrad)" opacity="0.9"/>');

  var svgStr='<svg viewBox="0 0 '+size+' '+size+'" width="260" height="260" xmlns="http://www.w3.org/2000/svg" style="display:block;margin:0 auto">'+
  '<defs>'+
  '<radialGradient id="needleGrad" cx="50%" cy="20%" r="80%">'+
  '<stop offset="0%" stop-color="#f0c060"/>'+
  '<stop offset="100%" stop-color="#b8860b"/>'+
  '</radialGradient>'+
  '</defs>'+
  parts.join('')+
  '</svg>';

  return svgStr;
}




