function getWestZodiac(m,d) {
  for(var i=0;i<WEST_ZODIAC.length;i++){
    var z=WEST_ZODIAC[i];
    if((m===z.m1&&d>=z.d1)||(m===z.m2&&d<=z.d2)) return z;
  }
  return WEST_ZODIAC[0];
}

function julianDay(y,m,d){
  var a=Math.floor((14-m)/12), yr=y+4800-a, mo=m+12*a-3;
  return d+Math.floor((153*mo+2)/5)+365*yr+Math.floor(yr/4)-Math.floor(yr/100)+Math.floor(yr/400)-32045;
}

// ══════════════════════════════════════════════════════════════
// 🛰️ NASA 실시간 태양 황도 기반 동적 만세력 (세계 최초)
// 전통 만세력: 수식 근사값 → 절기 당일 오차 발생
// NASA 융합:  태양 황도 실측 → 절기 분·초 단위 정밀 판별
// ══════════════════════════════════════════════════════════════

// 24절기 태양 황도 기준각 (°)
var SOLAR_TERMS_LON = [
  {lon:315, name:'소한', month:1},  // 1월
  {lon:330, name:'대한', month:1},
  {lon:345, name:'입춘', month:2},  // 2월 (인월 시작 ★)
  {lon:0,   name:'우수', month:2},
  {lon:15,  name:'경칩', month:3},  // 3월 (묘월 시작 ★)
  {lon:30,  name:'춘분', month:3},
  {lon:45,  name:'청명', month:4},  // 4월 (진월 시작 ★)
  {lon:60,  name:'곡우', month:4},
  {lon:75,  name:'입하', month:5},  // 5월 (사월 시작 ★)
  {lon:90,  name:'소만', month:5},
  {lon:105, name:'망종', month:6},  // 6월 (오월 시작 ★)
  {lon:120, name:'하지', month:6},
  {lon:135, name:'소서', month:7},  // 7월 (미월 시작 ★)
  {lon:150, name:'대서', month:7},
  {lon:165, name:'입추', month:8},  // 8월 (신월 시작 ★)
  {lon:180, name:'처서', month:8},
  {lon:195, name:'백로', month:9},  // 9월 (유월 시작 ★)
  {lon:210, name:'추분', month:9},
  {lon:225, name:'한로', month:10}, // 10월 (술월 시작 ★)
  {lon:240, name:'상강', month:10},
  {lon:255, name:'입동', month:11}, // 11월 (해월 시작 ★)
  {lon:270, name:'소설', month:11},
  {lon:285, name:'대설', month:12}, // 12월 (자월 시작 ★)
  {lon:300, name:'동지', month:12},
];

// 월건(月建) 절기 시작 황도 (입춘=315°부터 각 30°마다)
// 사주 월주: 입춘(315°) 기준 인월(寅月) 시작
var MONTH_START_LON = [315,345,15,45,75,105,135,165,195,225,255,285];
// 대응 지지: 인묘진사오미신유술해자축
var MONTH_JI_ORDER = ['寅','卯','辰','巳','午','未','申','酉','戌','亥','子','丑'];

/**
 * NASA 태양 황도로 정확한 사주 월주 계산
 * @param {number} sunLon - NASA JPL 실시간 태양 황도 (°)
 * @param {number} y - 연도 (월간 계산용)
 * @returns {gan, ji, term, termName} - 정밀 월주
 */
function getMonthGanJiNASA(sunLon, y) {
  var lon = ((sunLon % 360) + 360) % 360;

  // 현재 월건 인덱스 (0=인월, 1=묘월 ... 11=축월)
  var monthIdx = 0;
  for (var i = 0; i < 12; i++) {
    var startLon = MONTH_START_LON[i];
    var endLon   = MONTH_START_LON[(i + 1) % 12];
    // 황도 0° 넘는 구간 처리 (285°→315° 사이)
    var inRange;
    if (startLon > endLon) {
      inRange = (lon >= startLon || lon < endLon);
    } else {
      inRange = (lon >= startLon && lon < endLon);
    }
    if (inRange) { monthIdx = i; break; }
  }

  // 월지 (지지)
  var monthJi = MONTH_JI_ORDER[monthIdx];

  // 월간 (천간) — 연간 기준 오자법
  // 甲己년→丙寅시작, 乙庚년→戊寅, 丙辛년→庚寅, 丁壬년→壬寅, 戊癸년→甲寅
  var yearGanIdx = ((y - 4) % 10 + 10) % 10;
  var monthGanBase = [2, 4, 6, 8, 0][yearGanIdx % 5]; // 인월 시작 천간 인덱스
  var monthGan = GANS[(monthGanBase + monthIdx) % 10];

  // 현재 절기 이름
  var termName = '';
  var minDiff = 360;
  SOLAR_TERMS_LON.forEach(function(t) {
    var diff = Math.abs(lon - t.lon);
    if (diff > 180) diff = 360 - diff;
    if (diff < minDiff) { minDiff = diff; termName = t.name; }
  });

  // 절기까지 남은 각도 (다음 절기까지)
  var nextTermLon = MONTH_START_LON[(monthIdx + 1) % 12];
  var remaining = nextTermLon - lon;
  if (remaining < 0) remaining += 360;
  var remainDays = Math.round(remaining / 360 * 365.25);

  return {
    gan: monthGan,
    ji: monthJi,
    termName: termName,
    monthIdx: monthIdx,
    remainDays: remainDays,
    sunLon: lon.toFixed(2),
    isNASA: true
  };
}

/**
 * 오늘 날짜의 NASA 기반 일진(日辰) — 현재는 전통 방식과 동일하나
 * 향후 달 위상 보정 연동 가능
 */
function getDayGanJiNASA(y, m, d) {
  var jd = julianDay(y, m, d);
  var gan = GANS[((jd % 10) + 10) % 10];
  var ji  = JIJIS[((jd % 12) + 12) % 12];
  // NASA 달 위상으로 일진 에너지 보정값 계산
  var moonBonus = 0;
  if (window._nasaPlanets && window._nasaPlanets.moon) {
    var moonLon = parseFloat(window._nasaPlanets.moon.lon || 0);
    var sunLon2  = window._nasaPlanets.sun ? parseFloat(window._nasaPlanets.sun.lon || 0) : 0;
    var phase    = ((moonLon - sunLon2) % 360 + 360) % 360;
    // 보름(180°) 근처 — 에너지 최고조
    moonBonus = Math.round(Math.sin(phase * Math.PI / 180) * 5);
  }
  return { gan: gan, ji: ji, moonBonus: moonBonus, isNASA: true };
}

/**
 * 🛰️ NASA 동적 만세력 메인 함수
 * 기존 getMonthGanJi를 NASA 실시간으로 대체
 */
function getMonthGanJi(y, m) {
  // NASA 데이터 있으면 실시간 황도 기반
  if (window._nasaPlanets && window._nasaPlanets.sun) {
    var sunLon = parseFloat(window._nasaPlanets.sun.lon || 0);
    var result = getMonthGanJiNASA(sunLon, y);
    // 콘솔 로그 (디버깅용)
    if (window._LANG === 'ko') {
      console.log('[CGO-만세력] NASA 태양황도 ' + result.sunLon + '° → ' +
        result.gan + result.ji + '월 (' + result.termName + ' 후 ' + result.remainDays + '일)');
    }
    return result;
  }
  // NASA 없으면 기존 수식 폴백
  var gOff = [2, 4, 6, 8, 0][((y - 4) % 10 + 10) % 10 % 5];
  return { gan: GANS[(gOff + m - 1) % 10], ji: JIJIS[(m + 1) % 12], isNASA: false };
}

function getDayGanJi(y, m, d) {
  // NASA 달 위상 보정 포함
  return getDayGanJiNASA(y, m, d);
}

function getHourShiIdx(h){ return h===23?0:Math.floor((h+1)/2); }

function getHourGan(dayGanIdx, shiIdx){ return GANS[([0,2,4,6,8][dayGanIdx%5]+shiIdx)%10]; }

function calcLifeNum(y,m,d){
  var s=(y+('0'+m).slice(-2)+('0'+d).slice(-2)).split('').reduce(function(a,c){return a+parseInt(c);},0);
  while(s>9&&s!==11&&s!==22&&s!==33&&s!==44) s=(''+s).split('').reduce(function(a,c){return a+parseInt(c);},0);
  return s;
}

function calcKujusei(y,gender){
  var s=(''+y).split('').reduce(function(a,c){return a+parseInt(c);},0);
  while(s>9) s=(''+s).split('').reduce(function(a,c){return a+parseInt(c);},0);
  var k=gender==='M'?11-s:s+4;
  if(k<=0)k+=9; if(k>9)k-=9;
  return k;
}

function gradeInfo(n){
  if(n>=85)return{grade:'매우 좋음',desc:'하늘과 당신이 가장 잘 맞닿아 있는 날이에요 ✨',idx:4};
  if(n>=70)return{grade:'좋음',desc:'에너지가 고르게 흐르고 있어요. 믿고 나아가세요 🌙',idx:3};
  if(n>=55)return{grade:'보통',desc:'차분하게 균형을 유지하는 날이에요.',idx:2};
  if(n>=40)return{grade:'주의',desc:'오늘은 자신을 조금 더 돌봐 주세요 💛',idx:1};
  return{grade:'재충전',desc:'에너지를 모아두는 날이에요. 잘 쉬는 것이 내일의 힘이 돼요.',idx:0};
}

