function cplShowDetail(type){
  var panel=document.getElementById('cpl-detail-panel');
  var title=document.getElementById('cpl-detail-title');
  var body=document.getElementById('cpl-detail-body');
  if(!panel) return;
  var data=window._cplDetailData||{};
  var content=data[type];
  if(!content){ panel.style.display='none'; return; }
  if(panel.style.display!=='none'&&title&&title.dataset.type===type){
    panel.style.display='none'; return;
  }
  if(title){ title.textContent=content.title; title.dataset.type=type; }
  if(body) body.innerHTML=content.body;
  panel.style.display='block';
  panel.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function cplToggleCam(who){
  var video=document.getElementById('cpl-video-'+who);
  if(!video) return;
  if(video.style.display==='none'||!video.style.display){
    navigator.mediaDevices.getUserMedia({video:true,audio:false})
      .then(function(stream){
        video.srcObject=stream; video.style.display='block';
        var ph=document.getElementById('cpl-ph-'+who);
        if(ph) ph.style.display='none';
      }).catch(function(){ alert('카메라 접근 권한을 허용해주세요'); });
  } else {
    if(video.srcObject) video.srcObject.getTracks().forEach(function(t){t.stop();});
    video.style.display='none';
    var ph=document.getElementById('cpl-ph-'+who);
    if(ph) ph.style.display='flex';
  }
}
function cplLoadPhoto(who){
  var input=document.createElement('input');
  input.type='file'; input.accept='image/*';
  input.onchange=function(){
    var file=input.files[0]; if(!file) return;
    var reader=new FileReader();
    reader.onload=function(e){
      var img=document.getElementById('cpl-photo-'+who);
      var ph=document.getElementById('cpl-ph-'+who);
      if(img){ img.src=e.target.result; img.style.display='block'; }
      if(ph) ph.style.display='none';
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

