    ci:'1',
    an:_invNm,
    ay:r.y||'',am:r.m||'',ad:r.d||'',
    ah:r.h||'',ag:r.gender||'M',
    ao:r.domOh||'',al:r.lifeNum||'',
    af:bfd.faceType||(r.domOh?(r.domOh+'형'):''),
