    +'<div style="padding:12px;background:rgba(244,114,182,.06);border:1px solid rgba(244,114,182,.2);border-radius:10px;margin-bottom:12px;">'
    +'<div style="font-size:11px;color:rgba(240,230,200,.5);margin-bottom:6px;">초대 메시지:</div>'
