// 💑 CGO-FULI 실시간 영상 궁합 WebRTC 엔진
// ✨ C-24 (Claude Sonnet 4.6) — 2026.04.30
// Firebase 시그널링 + PeerJS + rPPG 양방향
// ══════════════════════════════════════════════════
var _cpl={peer:null,call:null,myCode:null,role:null,localStream:null,fbRef:null,rppgA:{score:50},rppgB:{score:50},_rppgInterval:null};

function _cplFB(){
  try{
    if(window.firebase&&firebase.apps&&firebase.apps.length) return firebase.database();
    var cfg={apiKey:'AIzaSyBwT8Dz1C07J-UK3V6Y1oj4-XJvxr6CXMg',databaseURL:'https://cgo-life-default-rtdb.firebaseio.com'};
    if(!firebase.apps.filter(function(a){return a.name==='cpl';}).length) firebase.initializeApp(cfg,'cpl');
    return firebase.app('cpl').database();
  }catch(e){return null;}
}

function cplCreateRoom(){
  var code=Math.random().toString(36).substr(2,5).toUpperCase()+'-'+Math.random().toString(36).substr(2,5).toUpperCase();
  _cpl.myCode=code; _cpl.role='host';
  var box=document.getElementById('cpl-room-code-box');
  var txt=document.getElementById('cpl-room-code-txt');
  if(box) box.style.display='block';
  if(txt) txt.textContent=code;
  var st=document.getElementById('cpl-room-status-txt');
  if(st) st.textContent=_cgoT('방 생성 완료 — 상대방 입장 대기 중...');
  var db=_cplFB();
  if(db){
    _cpl.fbRef=db.ref('cgo_cpl/'+code);
    _cpl.fbRef.set({host:'waiting',guest:'waiting',t:Date.now()});
    _cpl.fbRef.child('guest').on('value',function(snap){
      if(snap.val()==='joined'){
        if(st) st.textContent=_cgoT('✅ 상대방 입장! 카메라를 켜주세요');
        var dot=document.getElementById('cpl-room-status-dot');
        if(dot) dot.style.background='#34d399';
        _cplInitPeer(code,'host');
      }
    });
  }
  var live=document.getElementById('cpl-live-section');
  if(live) live.style.display='block';
}

function cplJoinRoom(){
  var input=document.getElementById('cpl-room-input');
  var code=input?input.value.trim():'';
  if(!code){alert('상대방 코드를 입력해주세요');return;}
  _cpl.myCode=code; _cpl.role='guest';
  var msg=document.getElementById('cpl-joined-msg');
  var show=document.getElementById('cpl-joined-code-show');
  if(msg) msg.style.display='block';
  if(show) show.textContent=_cgoT('코드: ')+code;
  var db=_cplFB();
  if(db){ _cpl.fbRef=db.ref('cgo_cpl/'+code); _cpl.fbRef.child('guest').set('joined'); _cplInitPeer(code,'guest'); }
  var live=document.getElementById('cpl-live-section');
  if(live) live.style.display='block';
}

function cplCopyRoomCode(){
  var txt=document.getElementById('cpl-room-code-txt');
  if(!txt) return;
  navigator.clipboard.writeText(txt.textContent).then(function(){
    alert('✅ 코드가 복사됐습니다!\n카톡·문자로 상대방에게 보내주세요');
  }).catch(function(){prompt('아래 코드를 복사하세요:',txt.textContent);});
}

function _cplInitPeer(code,role){
  if(typeof Peer==='undefined'){
    var s=document.createElement('script');
    s.src='https://unpkg.com/peerjs@1.5.4/dist/peerjs.min.js';
    s.onload=function(){_cplStartPeer(code,role);};
    document.head.appendChild(s);
  } else { _cplStartPeer(code,role); }
}

function _cplStartPeer(code,role){
  var pid=(role==='host'?'cgoh-':'cgog-')+code.replace('-','');
  try{_cpl.peer=new Peer(pid,{debug:1});}catch(e){_cpl.peer=new Peer();}
  _cpl.peer.on('open',function(){
    var st=document.getElementById('cpl-room-status-txt');
    if(role==='host'){
      _cpl.peer.on('call',function(call){
        _cpl.call=call;
        navigator.mediaDevices.getUserMedia({video:true,audio:false}).then(function(stream){
          _cpl.localStream=stream;
          _cplShowLocal(stream);
          call.answer(stream);
          call.on('stream',function(rs){_cplShowRemote(rs);_cplStartRppg();});
        }).catch(function(e){alert('카메라 오류: '+e.message);});
      });
      if(st) st.textContent=_cgoT('✅ 준비 완료 — 상대방 카메라 대기');
    } else {
      setTimeout(function(){
        navigator.mediaDevices.getUserMedia({video:true,audio:false}).then(function(stream){
          _cpl.localStream=stream;
          _cplShowLocal(stream);
          var hId='cgoh-'+code.replace('-','');
          var call=_cpl.peer.call(hId,stream);
          _cpl.call=call;
          if(call) call.on('stream',function(rs){_cplShowRemote(rs);_cplStartRppg();});
        }).catch(function(e){alert('카메라 오류: '+e.message);});
      },1200);
      if(st) st.textContent=_cgoT('✅ 연결 중...');
    }
  });
  _cpl.peer.on('error',function(){
    var st=document.getElementById('cpl-room-status-txt');
    if(st) st.textContent=_cgoT('⚠️ 연결 오류 — 방을 다시 만들어주세요');
  });
}

function _cplShowLocal(stream){
  var v=document.getElementById('cpl-video-a');
  var ph=document.getElementById('cpl-ph-a');
  if(v){v.srcObject=stream;v.style.display='block';}
  if(ph) ph.style.display='none';
}
function _cplShowRemote(stream){
  var v=document.getElementById('cpl-video-b-remote');
  var ph=document.getElementById('cpl-ph-b');
  if(v){v.srcObject=stream;v.style.display='block';}
  if(ph) ph.style.display='none';
  var st=document.getElementById('cpl-status-txt');
  if(st) st.textContent=_cgoT('🔴 C-24 rPPG 실시간 생체 파동 분석 중...');
}

function _cplStartRppg(){
  if(_cpl._rppgInterval) clearInterval(_cpl._rppgInterval);
  var canvas=document.createElement('canvas');
  canvas.width=64;canvas.height=48;
  var ctx=canvas.getContext('2d', { willReadFrequently: true });
  _cpl._rppgInterval=setInterval(function(){
    var vA=document.getElementById('cpl-video-a');
    if(vA&&vA.readyState>=2){
      ctx.drawImage(vA,0,0,64,48);
      var d=ctx.getImageData(20,10,24,28).data;
      var r=0,g=0,b=0,n=0;
      for(var i=0;i<d.length;i+=4){r+=d[i];g+=d[i+1];b+=d[i+2];n++;}
      if(n){r/=n;g/=n;b/=n;}
      var s=Math.min(100,Math.max(0,50+(g-r*0.5-b*0.5)*0.8));
      _cpl.rppgA.score=Math.round(_cpl.rppgA.score*0.85+s*0.15);
      _cplBar('a',_cpl.rppgA.score);
    }
    // B — WebRTC 원격 또는 로컬 카메라
    var vB=document.getElementById('cpl-video-b-remote');
    if(!vB||vB.readyState<2) vB=document.getElementById('cpl-video-b');
    if(vB&&vB.readyState>=2){
      ctx.drawImage(vB,0,0,64,48);
      var d2=ctx.getImageData(20,10,24,28).data;
      var r2=0,g2=0,b2=0,n2=0;
      for(var j=0;j<d2.length;j+=4){r2+=d2[j];g2+=d2[j+1];b2+=d2[j+2];n2++;}
      if(n2){r2/=n2;g2/=n2;b2/=n2;}
      var s2=Math.min(100,Math.max(0,50+(g2-r2*0.5-b2*0.5)*0.8));
      _cpl.rppgB.score=Math.round(_cpl.rppgB.score*0.85+s2*0.15);
      _cplBar('b',_cpl.rppgB.score);
    }
    var harmony=100-Math.abs(_cpl.rppgA.score-_cpl.rppgB.score);
    var total=Math.min(99,Math.max(1,Math.round(harmony*0.4+(_cpl.rppgA.score+_cpl.rppgB.score)*0.3)));
    var el=document.getElementById('cpl-total-score');
    if(el) el.textContent=total;
  },300);
}

function _cplBar(who,score){
  var bar=document.getElementById('cpl-bar-'+who);
  var barD=document.getElementById('cpl-bar-'+who+'-down');
  var sc=document.getElementById('cpl-score-'+who);
  if(bar) bar.style.height=Math.max(0,score-50)+'%';
  if(barD) barD.style.height=Math.max(0,50-score)+'%';
  if(sc) sc.textContent=score;
}

function cplToggleCam(who){
  // B 로컬 카메라 (WebRTC 미연결 시)
  var vid=who==='a'?'cpl-video-a':'cpl-video-b';
  var v=document.getElementById(vid);
  if(!v) return;
  if(_cpl.localStream&&who==='a'){
    var t=_cpl.localStream.getVideoTracks()[0];
    if(t) t.enabled=!t.enabled; return;
  }
  if(!v.srcObject){
    navigator.mediaDevices.getUserMedia({video:true,audio:false}).then(function(stream){
      if(who==='a') _cpl.localStream=stream;
      v.srcObject=stream; v.style.display='block';
      var ph=document.getElementById('cpl-ph-'+who);
      if(ph) ph.style.display='none';
      // B 카메라 켜면 rPPG 시작
      if(who==='b'&&document.getElementById('cpl-video-a').srcObject) _cplStartRppg();
    }).catch(function(){alert('카메라 접근 권한을 허용해주세요');});
  } else {
    v.srcObject.getTracks().forEach(function(t){t.stop();});
    v.srcObject=null; v.style.display='none';
    var ph2=document.getElementById('cpl-ph-'+who);
    if(ph2) ph2.style.display='flex';
  }
}

// ★ 작명 서비스 입구 팝업
// ★ AI 작명 해석 단독 재실행
function runNamingAi(){
  var aiText = document.getElementById('namingAiText');
  var aiStatus = document.getElementById('namingAiStatus');
  if(!aiText || !window._lastNamingPrompt) return;
  if(aiStatus) aiStatus.textContent = _cgoT('AI 재분석 중...');
  aiText.innerHTML = '<span style="color:rgba(212,168,67,.4);">🤖 '+_cgoT('AI 해설 생성 중...')+'</span>';
  window._namingAiT0=Date.now();
  fetch('/api/groq',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({
      model:'openai/gpt-oss-20b',reasoning_effort:'low',include_reasoning:false,
      max_tokens:1000,
      messages:[{role:'user',content:window._lastNamingPrompt}]
    })
  }).then(function(r){return r.json();})
  .then(function(d){
    var txt=(d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)||'';
    if(aiText&&txt){
      aiText.innerHTML=txt.replace(/\n/g,'<br>').replace(/\*\*(.*?)\*\*/g,'<b style="color:#d4a843;">$1</b>');
      if(aiStatus) aiStatus.textContent=_cgoT('✅ 완료')+' ('+((Date.now()-(window._namingAiT0||Date.now()))/1000).toFixed(1)+'s)';
    }
  }).catch(function(){
    if(aiText) aiText.textContent=_cgoT('AI 분석을 불러올 수 없습니다.');
  });
}

