// ★ cplAutoFill — 대시보드 데이터 자동 연동 (관상·손금 포함)
function cplAutoFill(){
  var r=window.calcResult||{};
  if(!r.y) return;
  var ay=document.getElementById('cpl-a-y');
  var am=document.getElementById('cpl-a-m');
  var ad=document.getElementById('cpl-a-d');
  var an=document.getElementById('cpl-a-name');
  if(ay&&!ay.value) ay.value=r.y||'';
  if(am&&!am.value) am.value=r.m||'';
  if(ad&&!ad.value) ad.value=r.d||'';
  if(an&&!an.value) an.value=r.name||'';
  // 관상·손금 생체 스캔 연동
  var bfd=window._bioFinalData||{};
  var aFace=document.getElementById('cpl-a-face');
  var aPalm=document.getElementById('cpl-a-palm');
  if(aFace&&bfd.faceType&&!aFace.value) aFace.value=bfd.faceType;
  if(aPalm&&bfd.palmType&&!aPalm.value) aPalm.value=bfd.palmType;
  // 오행형 자동 입력
  if(aFace&&r.domOh&&!aFace.value){
    var ohMap={목:'목형(木型)',화:'화형(火型)',토:'토형(土型)',금:'금형(金型)',수:'수형(水型)'};
    aFace.value=ohMap[r.domOh]||'';
  }
}
