// ★ 보호대상 번호 추가
function famAddGuardTel(){
  var input=document.getElementById('fam-guard-tel');
  var tel=input.value.replace(/[^0-9]/g,'');
  if(tel.length<10){ alert('전화번호를 정확히 입력해주세요'); return; }
  var list=[];
  try{ list=JSON.parse(localStorage.getItem('cgo_guard_tels')||'[]'); }catch(e){}
  if(list.indexOf(tel)===-1) list.push(tel);
  localStorage.setItem('cgo_guard_tels', JSON.stringify(list));
  input.value='';
  famRenderGuardList();
}
function famRenderGuardList(){
  var el=document.getElementById('fam-guard-list'); if(!el) return;
  var list=[];
  try{ list=JSON.parse(localStorage.getItem('cgo_guard_tels')||'[]'); }catch(e){}
  if(list.length===0){ el.innerHTML=''; return; }
  el.innerHTML=list.map(function(tel,i){
    var disp=tel.replace(/(\d{3})(\d{3,4})(\d{4})/,'$1-$2-$3');
    return '<div style="display:flex;justify-content:space-between;align-items:center;padding:5px 8px;background:rgba(56,189,248,.05);border-radius:8px;margin-top:4px;">'+
      '<span style="font-size:12px;color:#38bdf8;">🛡️ '+disp+'</span>'+
      '<button onclick="famDelGuardTel('+i+')" style="background:none;border:none;color:rgba(248,113,113,.6);cursor:pointer;font-size:11px;">✕</button>'+
      '</div>';
  }).join('');
}
function famDelGuardTel(i){
  var list=[];
  try{ list=JSON.parse(localStorage.getItem('cgo_guard_tels')||'[]'); }catch(e){}
  list.splice(i,1);
  localStorage.setItem('cgo_guard_tels', JSON.stringify(list));
  famRenderGuardList();
}

