// 약식(48) = 각 축 12문항, 정식(93) = 각 축 ~23문항, 정밀(144) = 전체
var MSP_Q_SETS = {
  simple:  {label:'약식', total:48,  per:12, color:'#34d399', time:'8~10분'},
  standard:{label:'표준', total:92,  per:23, color:'#a855f7', time:'15~20분'},
  precise: {label:'심층', total:144, per:36, color:'#d4a843', time:'25~30분'}
};

var _mspState = {
  mode:null, testType:'simple',
  qIdx:0, questions:[],
  scores:{E:0,I:0,S:0,N:0,T:0,F:0,J:0,P:0},
  result:null
};
window._mspResult = null;

// STEP1: 아는지 모르는지 선택
function mspGo(type) {
  document.getElementById('mspStep1').style.display = 'none';
  if (type === 'know') {
    document.getElementById('mspKnowPanel').style.display = 'block';
    mspRenderTypeGrid();
  } else {
    document.getElementById('mspTestSelect').style.display = 'block';
  }
}

// ← 되돌리기 — Step1으로 복귀
function mspBackToStep1() {
  ['mspKnowPanel','mspTestSelect','mspTestPanel','mspResult'].forEach(function(id){
    var el = document.getElementById(id);
    if(el) el.style.display = 'none';
  });
  var s1 = document.getElementById('mspStep1');
  if(s1) s1.style.display = 'grid';
}

// ✅ 음성 안내 ON/OFF 토글
function cgoToggleTTS() {
  window._ttsEnabled = !window._ttsEnabled;
  var btn  = document.getElementById('ttsToggleBtn');
  var txt  = document.getElementById('ttsStatusTxt');
  var ico  = document.getElementById('ttsIconBadge');
  if(window._ttsEnabled) {
    if(btn){ btn.textContent='ON'; btn.style.borderColor='rgba(52,211,153,.5)'; btn.style.background='rgba(52,211,153,.12)'; btn.style.color='#34d399'; }
    if(txt){ txt.textContent=_cgoT('켜짐 — 스캔 중 음성 지시 제공'); txt.style.color='rgba(52,211,153,.7)'; }
    if(ico) ico.textContent='🔊';
    if(window.speechSynthesis) window.speechSynthesis.cancel();
  } else {
    if(btn){ btn.textContent='OFF'; btn.style.borderColor='rgba(248,113,113,.4)'; btn.style.background='rgba(248,113,113,.08)'; btn.style.color='#f87171'; }
    if(txt){ txt.textContent=_cgoT('꺼짐 — 화면 팝업 지시로 대체'); txt.style.color='rgba(248,113,113,.6)'; }
    if(ico) ico.textContent='🔇';
    if(window.speechSynthesis) window.speechSynthesis.cancel();
  }
}

// 📋 스캔 지시사항 패널 토글
function cgoToggleBioGuide() {
  var panel = document.getElementById('bioGuidePanel');
  var arrow = document.getElementById('bioGuideArrow');
  if(!panel) return;
  var isOpen = panel.style.display !== 'none';
  panel.style.display = isOpen ? 'none' : 'block';
  if(arrow) arrow.style.transform = isOpen ? '' : 'rotate(180deg)';
}

// 직접 선택 그리드
function mspRenderTypeGrid() {
  var grid = document.getElementById('mspTypeGrid');
  var ohColor = {목:'#34d399',화:'#f87171',토:'#fbbf24',금:'#d4a843',수:'#38bdf8'};
  var keys = ['하늘','바람','불꽃','태산','대지','무쇠','샘물','심해'];
  grid.innerHTML = keys.map(function(k) {
    var K = CGO_KIRYU[k]; if(!K) return '';
    var c = ohColor[K.oh] || '#a78bfa';
    return '<div onclick="mspSelectKiryu(\''+k+'\')" style="background:rgba(168,85,247,.06);border:1px solid '+c+'44;border-radius:12px;padding:15px 12px;cursor:pointer;text-align:center;transition:.15s;">'
      +'<div style="font-size:26px;line-height:1;margin-bottom:5px;">'+K.ico+'</div>'
      +'<div style="font-size:13px;font-weight:800;color:'+c+';">'+k+' 기류</div>'
      +'<div style="font-size:8.5px;color:rgba(196,181,253,.7);margin-top:3px;">'+K.theme+'</div>'
      +'</div>';
  }).join('');
}
// ★ 8기류 직접 선택 → 평범형(normal) 결과
function mspSelectKiryu(kiryu){
  var K = CGO_KIRYU[kiryu]; if(!K) return;
  var ohRep = {화:'ENFP',목:'ENTP',토:'ISFJ',금:'ISTJ',수:'INFJ'};
  var repType = ohRep[K.oh] || 'INFJ';
  var info = MSP_TYPES[repType] || {};
  window._mspResult = {type:repType, oh:K.oh, boost:info.boost, trait:info.trait, source:'직접선택',
    kiryu:kiryu, kiryuName:(K.names&&K.names.normal)||'', kiryuIco:K.ico, kiryuTheme:K.theme,
    axisStrength:{dir:0,eye:0,dec:0,flow:0}};
  document.getElementById('mspKnowPanel').style.display = 'none';
  mspShowResult();
}

function mspSelectType(type) {
  var info = MSP_TYPES[type];
  if (!info) return;
  window._mspResult = {type:type, oh:info.oh, boost:info.boost, trait:info.trait, source:'직접선택'};
  document.getElementById('mspKnowPanel').style.display = 'none';
  mspShowResult();
}

// 검사 시작
function mspStartTest(testType) {
  _mspState.testType = testType;
  var cfg = MSP_Q_SETS[testType];
  // 4축에서 per개씩 뽑기
  var axes = ['EI','SN','TF','JP'];
  var qs = [];
  axes.forEach(function(ax) {
    var pool = _MSP_Q_ALL.filter(function(q){ return q.axis === ax; });
    qs = qs.concat(pool.slice(0, cfg.per));
  });
  // 섞기 (축별로 고르게 분산)
  var shuffled = [];
  var idx = [0,0,0,0]; var ai = 0;
  for (var i = 0; i < qs.length; i++) {
    shuffled.push(qs[(ai * cfg.per + idx[ai]) % qs.length]);
    idx[ai]++; ai = (ai+1) % 4;
  }
  _mspState.questions = qs;
  _mspState.qIdx = 0;
  _mspState.scores = {E:0,I:0,S:0,N:0,T:0,F:0,J:0,P:0};

  document.getElementById('mspTestSelect').style.display = 'none';
  document.getElementById('mspTestPanel').style.display = 'block';
  mspShowQ();
}

function mspShowQ() {
  _mspState._qStartTime = Date.now(); // ✅ 문항 표시 시작 시간
  var qs = _mspState.questions;
  var idx = _mspState.qIdx;
  if (idx >= qs.length) { mspCalcResult(); return; }
  var q = qs[idx];
  var cfg = MSP_Q_SETS[_mspState.testType];
  var axNames = {EI:'외향·내향 (E/I)', SN:'감각·직관 (S/N)', TF:'사고·감정 (T/F)', JP:'판단·인식 (J/P)'};
  document.getElementById('mspQText').textContent = _cgoT(q.q);
  document.getElementById('mspQLabel').textContent = (idx+1) + ' / ' + cfg.total;
  document.getElementById('mspAxisLabel').textContent = axNames[q.axis] || q.axis;
  document.getElementById('mspAxisLabel').style.color = cfg.color;
  document.getElementById('mspProgressBar').style.width = ((idx+1)/cfg.total*100) + '%';
  document.getElementById('mspProgressBar').style.background = 'linear-gradient(90deg,'+cfg.color+',#38bdf8)';
}

// 5단계 응답 (-2,-1,0,+1,+2)
function mspAnswer(val) {
  var q = _mspState.questions[_mspState.qIdx];
  if (!q) return;
  // ✅ 응답 시간 기록
  var now = Date.now();
  var elapsed = _mspState._qStartTime ? (now - _mspState._qStartTime) : 0;
  if (!_mspState._times) _mspState._times = [];
  _mspState._times.push(elapsed);
  _mspState._qStartTime = null;
  // p 방향으로 val만큼 점수 부여
  var opposites = {E:'I',I:'E',S:'N',N:'S',T:'F',F:'T',J:'P',P:'J'};
  if (val > 0) {
    _mspState.scores[q.p] += val;
  } else if (val < 0) {
    _mspState.scores[opposites[q.p]] += Math.abs(val);
  }
  // 중립(0)은 양쪽 0.5씩
  _mspState.qIdx++;
  mspShowQ();
}

