      badge.innerHTML = '<div style="margin-top:8px;padding:10px 14px;background:linear-gradient(135deg,rgba(212,168,67,.3),rgba(251,191,36,.2));border:2px solid #d4a843;border-radius:12px;text-align:center;animation:goldPulse 1.5s ease-in-out infinite;">'
        +'<div style="font-size:18px;margin-bottom:4px;">🎰✨🎰</div>'
