  appState.name=calcResult.name; appState.year=y; appState.month=m; appState.day=d; appState.hour=h;
  appState.ili=ili; appState.scores=scores;
  appState.birthPlace=birthPlace; appState.birthLat=birthLat; appState.birthLng=birthLng;
  appState.curPlace=curPlace; appState.curLat=curLat; appState.curLng=curLng;
