      var bg=f.ili>=80?'var(--green-dim)':f.ili<60?'var(--red-dim)':'var(--cyan-dim)';
      var _familyMsg = typeof getFamilyIliMsg==='function' ? getFamilyIliMsg(f) : '';
      return '<div class="af-item"><div class="af-badge" style="background:'+bg+'">'+ic+'</div><div><div class="af-text">'+(_famEN&&f.name==='사용자'?'User':f.name)+' ILI '+f.ili+' — '+(_famEN?(_FAM_GRADE_EN[gradeInfo(f.ili).grade]||gradeInfo(f.ili).grade):gradeInfo(f.ili).grade)+'</div>'+(_familyMsg?'<div style="font-size:11px;color:rgba(240,230,200,.6);margin-top:3px">'+_familyMsg+'</div>':'')+'<div class="af-time">'+(_famEN?'just now':'방금')+'</div></div></div>';
