function confirmAdd(){
  var name=document.getElementById('m-name').value.trim();
  var birth=document.getElementById('m-birth').value;
  var time=document.getElementById('m-time').value||'12:00';
  var role=document.getElementById('m-role').value;
  var gender=document.getElementById('m-gender').value;
  var phone=(document.getElementById('m-phone').value||'').replace(/[^0-9]/g,'');
  if(!name||!birth){alert_cgoTX('이름과 생년월일을 입력해주세요','Please enter name and date of birth');return;}
  var parts=birth.split('-').map(Number);
  var y=parts[0],m=parts[1],d=parts[2];
  var zi=((y-4)%12+12)%12;
  var wz=getWestZodiac(m,d);
  var ln=calcLifeNum(y,m,d);
  var colors=['var(--green)','var(--cyan)','var(--indigo)','var(--amber)','var(--red)'];
  // CGO-MASTER 기반 ILI 추정 (역학 계산 기반)
  var M = window._CGO_MASTER;
  var baseILI = M ? M.ili : 70;
  var lnAdj = [0,5,2,7,-2,3,4,8,9,-3][ln%10] || 0;
  var ageAdj = new Date().getFullYear()-y;
  ageAdj = ageAdj<10?3:ageAdj<20?5:ageAdj<40?2:ageAdj<60?0:-2;
  var seedAdj = (y+m+d+ln)%15 - 7; // -7~+7 결정론적 편차
  var ili = Math.min(95, Math.max(44, Math.round(baseILI*0.4 + 65*0.6 + lnAdj + ageAdj*0.5 + seedAdj)));
  var age=new Date().getFullYear()-y;
  var trendVal = (y+m+d)%10 >= 5 ? '+' : '';
  trendVal += Math.floor(Math.abs((y+m+d)%8)-3);
  var member={id:nextFamilyId++,name:name,role:role+(age?' ('+age+'세)':''),
    emoji:ZODIAC_EMOJI[zi],ili:ili,trend:trendVal,
    color:colors[familyData.length%colors.length],last:'방금',
    zodiacName:ZODIAC_NAMES[zi],wz:wz,lifeNum:ln,phone:phone};
  familyData.push(member);
  closeModal();
  renderFamily();
  document.getElementById('m-name').value='';
  document.getElementById('m-birth').value='';
  document.getElementById('m-phone').value='';
  var sf=document.getElementById('stat-family');
  if(sf)sf.textContent=familyData.length;
}

