    try{ var _tfo=document.getElementById('todayFortuneOverlay'); if(_tfo) _tfo.style.display='none'; var _pmi=document.getElementById('pm-intro-pop'); if(_pmi) _pmi.style.display='none'; document.body.style.overflow=''; }catch(e){}  /* ★ C-64: 순수역학 오버레이 확실히 닫기 */
    try{ if(window._cgoHideFeatBar) window._cgoHideFeatBar(); }catch(e){}  /* ★ C-64: 언어바 복원 */
    if(typeof bsCloseFullscreen==='function') bsCloseFullscreen();
    document.querySelectorAll('.nav-btn').forEach(function(b){b.classList.remove('active');});
