function goScan(){
  document.querySelectorAll('.nav-btn').forEach(function(b){b.classList.remove('active');});
  document.querySelector('[data-page="scan"]').classList.add('active');
  document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active');});
  document.getElementById('page-scan').classList.add('active');
  var _sTxt=document.getElementById('pageTitleText'); if(_sTxt){_sTxt.style.display='block';_sTxt.textContent=_cgoT('🎵 나의 주파수 음악');}

  // ── 2단계 음악 추천 구조 ──
  // 1단계: calcResult(정보입력) → 만세력+NASA 기반 음악
  // 2단계: _baiScanned(생체스캔) → 생체신호 추가 정밀 음악
  var bfd = window._bioFinalData||{};
  var scanned = window._baiScanned || (bfd.fci>0 || bfd.hrv>0);
  var hasCalc = !!(window.calcResult && window.calcResult.domOh);
  var lockNotice = document.getElementById('music-lock-notice');
  var musicBox = document.getElementById('bsMusicBox');
  var _musicStageEl = document.getElementById('_musicStageLabel');

  if(hasCalc || scanned){
    if(lockNotice) lockNotice.style.display='none';
    if(musicBox) musicBox.style.display='block';
    // 단계 레이블 업데이트
    if(_musicStageEl){
      _musicStageEl.textContent = scanned
        ? '🧬 2단계: 생체신호 × 역학 융합 정밀 가이드'
        : '📜 1단계: 만세력 × NASA 실시간 기반 추천';
      _musicStageEl.style.color = scanned ? '#34d399' : '#d4a843';
    }
    // 음악 추천 실행
    if(typeof bsMusicRecommend==='function' && window._lastMusicILI)
      bsMusicRecommend(window._lastMusicILI);
    else if(typeof bsMusicRecommend==='function' && window.calcResult)
      bsMusicRecommend(window.calcResult.ili||70);
  } else {
    if(lockNotice) lockNotice.style.display='block';
    if(musicBox) musicBox.style.display='none';
  }

  // ── 스캔 완료 상태면 음악·18개 분석·리포트 즉시 복원 ──
  if (window._baiScanned && window._lastMusicILI) {
    setTimeout(function(){
      var _mc = document.getElementById('bsMusicCards');
      var _mb = document.getElementById('bsMusicBox');
      if (_mb && _mc && _mc.children.length === 0) {
        _mb.style.display = 'block';
        if (typeof bsMusicRecommend === 'function') bsMusicRecommend(window._lastMusicILI);
      }
      var _rp = document.getElementById('expertReportPanel');
      var _rb = document.getElementById('expertReportBody');
      if (_rp && _rb && _rb.innerHTML === '' && typeof generateExpertReport === 'function') {
        _rp.style.display = 'block';
        _rb.innerHTML = generateExpertReport(window._lastMusicILI, [], {});
      }
    }, 150);
  }
}

// ── CGO-MASTER → 스캔 페이지 패널 실시간 업데이트 ──
function _updateScanMasterPanel(){
  var M = window._CGO_MASTER;
  var panel = document.getElementById('scanMasterPanel');
  if(!panel) return;

  // 대시보드 미계산 시 숨김
  if(!M && !(window.calcResult && window.calcResult.ili)){
    panel.style.display = 'none';
    return;
  }
  panel.style.display = 'block';

  var ili  = M ? M.ili  : (window.calcResult ? window.calcResult.ili : 0);
  var bai  = M ? M.bai  : 0;
  var cei  = M ? M.cei  : ili;
  var oh   = M ? M.domOh : (window.calcResult ? window.calcResult.domOh : '--');
  var ohMap = {목:'🌳木',화:'🔥火',토:'⛰土',금:'⚔金',수:'💧水'};
  var bio  = M ? M.bio  : {};

  // ★ _cgoGetScore() 로 신버전 통합 점수 획득
  var gs = (typeof _cgoGetScore === 'function') ? _cgoGetScore() : null;
  if(gs) {
    ili = gs.ili;
    bai = gs.bai;
    cei = gs.cei;
  }

  // 수치 업데이트
  var iel = document.getElementById('scanMasterILI'); if(iel) iel.textContent = ili||'--';
  var bel = document.getElementById('scanMasterBAI'); if(bel) bel.textContent = bai>0?bai:'--';
  var cel = document.getElementById('scanMasterCEI');
  if(cel){
    cel.textContent = gs ? gs.score : (cei||'--');
    // 스캔 완료 시 CEI 모드 표시, 미완료 시 ILI 표시
    cel.title = gs ? gs.breakdown : '';
  }
  var oel = document.getElementById('scanMasterOh');  if(oel) oel.textContent = ohMap[oh]||oh||'--';

  // 생체 실측값 행 — 자세한 설명 포함
  var bioRow = document.getElementById('scanMasterBioRow');
  var bioTxt = document.getElementById('scanMasterBioTxt');
  if(bio.scanned && (bio.hrv>0||bio.fci>0)){
    if(bioRow) bioRow.style.display = 'block';
    if(bioTxt) bioTxt.textContent =
      _cgoT('HRV(심박변이도):')+bio.hrv
      + ' · FCI(안면혈색):'+bio.fci
      + ' · BLI(손금):'+bio.bli
      + ' · BPM(심박수):'+bio.bpm;
  } else {
    if(bioRow) bioRow.style.display = 'none';
  }

  // CEI 배지 색상 (점수에 따라)
  var cEl = document.getElementById('scanMasterCEI');
  if(cEl && gs) cEl.style.color = gs.color;
  else if(cEl) cEl.style.color = cei>=85?'#34d399':cei>=70?'#38bdf8':cei>=55?'#fbbf24':'#f87171';

  // 갱신 시각
  var timeEl = document.getElementById('scanMasterTime');
  if(timeEl && M && M.updatedAt){
    var t = M.updatedAt;
    timeEl.textContent = t.getHours()+':'+String(t.getMinutes()).padStart(2,'0')+' 기준';
  }

  // AI 퓨전 패널 — _cgoGetScore 기반 신버전 반영
  if(ili > 0){
    var bsIli = document.getElementById('bsFIli');
    var bsYuk = document.getElementById('bsFYuk');
    var bsBio = document.getElementById('bsFBio');
    var bsGrd = document.getElementById('bsFGrade');
    var bsSub = document.getElementById('bsFIliSub');
    var finalScore = gs ? gs.score : cei;
    if(bsIli && bsIli.textContent==='--'){
      if(bsIli) bsIli.textContent = finalScore;
      if(bsYuk) bsYuk.textContent = Math.min(92,Math.round(ili*0.95));
      if(bsBio) bsBio.textContent = bai>0?bai:Math.min(88,Math.round(ili*0.85));
      var grd = finalScore>=85?'S+':finalScore>=75?'A':finalScore>=65?'B':'C';
      if(bsGrd) bsGrd.textContent = grd+(bio.scanned?' ★생체실측':'');
      if(bsSub) bsSub.textContent = gs && gs.scanned
        ? gs.mode+' '+gs.score+'점 — '+gs.gradeMsg
        : '역학 ILI 기반 예측 (생체 스캔 시 CEI로 업그레이드)';
    }
  }
}

