function saveProfile(){
  // ── 값 읽기 ──
  var name  = (document.getElementById('prof-name')||{value:''}).value.trim();
  var birthY= (document.getElementById('prof-birth-y')||{value:''}).value.trim();
  var birthM= (document.getElementById('prof-birth-m')||{value:''}).value.trim();
  var birthD= (document.getElementById('prof-birth-d')||{value:''}).value.trim();
  var time  = (document.getElementById('prof-time')||{value:''}).value.trim();
  var gender= (document.getElementById('prof-gender')||{value:'male'}).value;
  var bPlace= (document.getElementById('prof-birth-place')||{value:''}).value.trim();
  var cPlace= (document.getElementById('prof-cur-place')||{value:''}).value.trim();

  if(!name){ alert('이름을 입력해 주세요!'); return; }

  // ── localStorage 저장 ──
  localStorage.setItem('cgo_prof_name',   name);
  localStorage.setItem('cgo_prof_birth_y', birthY);
  localStorage.setItem('cgo_prof_birth_m', birthM);
  localStorage.setItem('cgo_prof_birth_d', birthD);
  localStorage.setItem('cgo_prof_time',   time);
  localStorage.setItem('cgo_prof_gender', gender);
  if(bPlace) localStorage.setItem('cgo_birth_place', bPlace);
  if(cPlace) localStorage.setItem('cgo_cur_place',   cPlace);

  // ── 상단 이름·아바타 반영 ──
  var setTxt = function(id,v){ var e=document.getElementById(id); if(e) e.textContent=v; };
  setTxt('profName', name);
  setTxt('topName',  name);
  setTxt('topAvatar',  name.charAt(0));
  setTxt('sbAvatar',   name.charAt(0));

  // ── 대시보드 입력 필드 전체 자동 반영 ──
  var setVal = function(id,v){ var e=document.getElementById(id); if(e&&v) e.value=v; };

  // 이름
  setVal('ipName', name);

  // 생년월일 (년/월/일 분리 필드)
  setVal('ipBirthY', birthY);
  setVal('ipBirthM', birthM);
  setVal('ipBirthD', birthD);

  // 생년월일 hidden 필드 동기화
  if(birthY && birthM && birthD){
    var mm = birthM.padStart(2,'0');
    var dd = birthD.padStart(2,'0');
    var dateStr = birthY+'-'+mm+'-'+dd;
    setVal('ipBirth', dateStr);
    // prof-birth (date타입) 도 동기화
    setVal('prof-birth', dateStr);
  }

  // 출생 시간
  setVal('ipTime', time);

  // 성별
  var gSel = document.getElementById('ipGender');
  if(gSel) gSel.value = gender;

  // 출생지
  if(bPlace){
    setVal('ipBirthPlace', bPlace);
    var bpEl = document.getElementById('ipBirthPlace');
    if(bpEl) bpEl.dispatchEvent(new Event('input'));
  }

  // 현재 거주지
  if(cPlace){
    setVal('ipCurPlace', cPlace);
    var cpEl = document.getElementById('ipCurPlace');
    if(cpEl) cpEl.dispatchEvent(new Event('input'));
  }

  // syncBirthField 호출해서 내부 계산도 동기화
  if(typeof syncBirthField === 'function') syncBirthField();

  // ── CGO-MASTER 프로필 변경 → 자동 재계산 유도 ──
  var _profileBirth = (birthY&&birthM&&birthD) ? birthY+'-'+birthM.padStart(2,'0')+'-'+birthD.padStart(2,'0') : '';
  if(_profileBirth && typeof calcAstro === 'function'){
    // 대시보드로 이동 후 자동 계산 트리거
    setTimeout(function(){
      var calcBtn = document.getElementById('calcBtn');
      if(calcBtn) calcBtn.style.boxShadow = '0 0 0 3px rgba(52,211,153,.5)';
    }, 300);
  }

  // ── 완료 알림 ──
  alert('✅ 저장 완료!\n대시보드의 모든 입력 필드에 자동 반영되었습니다.\n바로 ⚡ 자동 계산을 눌러보세요!');
}

