// 대시보드 호흡 미니 위젯
// ═══════════════════════════════════════════
var _dbBreath = {on:false, phase:0, sec:0, tId:null, done:false};
var _dbBreathPhases = [
  {l:'들숨',s:4,c:'#38bdf8'},
  {l:'참기',s:7,c:'#d4a843'},
  {l:'날숨',s:8,c:'#34d399'}
];

function dbBreathStart(){
  if(_dbBreath.done) return;
  clearInterval(_dbBreath.tId);
  _dbBreath.phase=0; _dbBreath.sec=0; _dbBreath.on=true;
  var btn=document.getElementById('db-breath-btn');
  if(btn){btn.textContent=_cgoT('● 진행 중');btn.disabled=true;}
  _breathEngineStart && _breathEngineStart();
  // ✅ _cgoSpeak onDone 체인 — PC:TTS완료후, 스마트폰:자막+비프음후 카운트시작
  // 안내방송 없음
  _dbBreath.tId=setInterval(_dbBreathTick,1000);
  _dbBreathTick();
}

function dbBreathStop(){
  clearInterval(_dbBreath.tId); _dbBreath.on=false;
  var btn=document.getElementById('db-breath-btn');
  if(btn&&!_dbBreath.done){btn.textContent=_cgoT('▶ 호흡 시작');btn.disabled=false;}
  var ph=document.getElementById('db-breath-phase');
  if(ph&&!_dbBreath.done) ph.textContent=_cgoT('시작 버튼을 눌러주세요');
}

function _dbBreathTick(){
  var ph=_dbBreathPhases[_dbBreath.phase];
  var rem=ph.s-_dbBreath.sec;
  var el=document.getElementById('db-breath-phase');
  if(el){el.textContent=ph.l+' — '+rem+'초';el.style.color=ph.c;}
  _dbBreath.sec++;
  if(_dbBreath.sec>ph.s){
    _dbBreath.sec=0;
    _dbBreath.phase=(_dbBreath.phase+1)%3;
    if(_dbBreath.phase===0){
      // 1사이클 완료
      clearInterval(_dbBreath.tId); _dbBreath.done=true;
      _breathEngineStop && _breathEngineStop();
      var result=_breathCalcScore ? _breathCalcScore() : {score:72,method:'타이밍'};
      var sc=result.score;
      var ph2=document.getElementById('db-breath-phase');
      if(ph2){ph2.textContent=_cgoT('✅ 완료 — 안정도 ')+sc+'%';ph2.style.color='#34d399';}
      var box=document.getElementById('db-breath-score-box');
      var scEl=document.getElementById('db-breath-score');
      if(box)box.style.display='block';
      if(scEl)scEl.textContent=sc;
      var btn=document.getElementById('db-breath-btn');
      if(btn){btn.textContent=_cgoT('✅ 완료');btn.disabled=false;}
      // HRV 엔진 반영
      if(typeof _hvset==='function' && window.calcResult) _hvset(1,sc,'NASA 행성 트랜짓 × 호흡 에너지 반영',true);
      // 단일 저장소에 최신 호흡 점수 저장 → 건강페이지 동기화
      window._lastBreathScore = sc;
      if(typeof _HV!=='undefined') _HV.bScore=sc;
      if(typeof hltSyncBioCards==='function') setTimeout(function(){ hltSyncBioCards(); },200);
    }
  }
}

