// 대시보드 체온 미니 위젯
// ═══════════════════════════════════════════
function dbTempStart(){
  var btn=document.getElementById('db-temp-btn');
  if(btn){btn.textContent=_cgoT('🌡️ 측정 중...');btn.disabled=true;}
  var st=document.getElementById('db-temp-status');
  if(st) st.textContent=_cgoT('📱 센서 수집 중... (2초)');
  window._cgoSpeak('케이스가 있으면 뒷면을 넘겨 맨 폰이 손바닥에 닿도록 하세요. 양손으로 감싸 쥐고 고정해 주세요.');
  // 기존 체온 엔진 재사용
  if(typeof _tempEngineCollect==='function'){
    _tempEngineCollect(function(){
      var temp=typeof _tempCalcFromSensors==='function'?_tempCalcFromSensors():36.5;
      var tv=document.getElementById('db-temp-val');
      var col=temp<36?'#38bdf8':temp<37?'#fbbf24':temp<37.5?'#f97316':'#f87171';
      if(tv){tv.textContent=temp.toFixed(1);tv.style.color=col;}
      var st2=document.getElementById('db-temp-status');
      var method=(typeof _tempEngine!=='undefined'&&_tempEngine.hasRealData)?'📷센서실측':'⏱일주기분석';
      if(st2){st2.textContent='✅ '+temp.toFixed(1)+'°C — '+method;st2.style.color=col;}
      if(btn){btn.textContent=_cgoT('✅ 측정 완료');btn.disabled=false;}
      // 체온 엔진 반영
      var diff=Math.abs(temp-36.5);
      var sc=diff<0.2?88:diff<0.5?75:diff<1.0?62:48;
      sc=Math.max(45,Math.min(96,sc));
      if(typeof _hvset==='function' && window.calcResult) _hvset(3,sc,'기문둔갑 지자기 × 온기 에너지',true);
      // 단일 저장소에 최신 체온 점수 저장 → 건강페이지 동기화
      window._lastTempScore = sc;
      window._lastTempVal = temp;
      if(typeof _HV!=='undefined') _HV.tmpScore=sc;
      if(window.appState&&window.appState.bio) window.appState.bio.temp=temp;
      if(typeof hltSyncBioCards==='function') setTimeout(function(){ hltSyncBioCards(); },200);
    });
  } else {
    // 폴백
    var temp=36.5;
    var tv=document.getElementById('db-temp-val');
    if(tv){tv.textContent=temp.toFixed(1);tv.style.color='#fbbf24';}
    var st3=document.getElementById('db-temp-status');
    if(st3) st3.textContent='✅ '+temp.toFixed(1)+'°C';
    if(btn){btn.textContent=_cgoT('✅ 측정 완료');btn.disabled=false;}
    // 폴백도 동기화
    if(typeof _HV!=='undefined') _HV.tmpScore=75;
    if(typeof hltSyncBioCards==='function') setTimeout(function(){ hltSyncBioCards(); },200);
  }
}

// ═══════════════════════════════════════════════════════
// 🛡️ MUFE 1단계 — 인지 비대칭 동적 인증 시스템
// PCT 특허: 인공지능의 학습 한계와 인간 고유의
// 비정형 인지 특성을 역이용한 동적 다중 인증 시스템
// ═══════════════════════════════════════════════════════

var _MUFE = {
  verified: false,
  attempts: 0,
  maxAttempts: 5,
  currentChallenge: null,
  hiddenWord: '',
  // 카오스 텍스트 생성용 특수문자 풀
  noiseChars: '?#ㅣ&@원>ㅓㅏㅂ주ㄱㄴ*5ㄷ○!~이?○ㅅ%?%-ㅊㅍㅎㄹㅇ$&○ㅑㅣㅂ주ㄱ@#!*?ㅛ%&>ㄱㄴ',
  // Shannon 엔트로피 기반 카오스 레이어 생성
  generateChaosText: function(hiddenWord) {
    var noise = _MUFE.noiseChars;
    var result = '';
    var wLen = hiddenWord.length;
    // 단어를 랜덤 위치에 분산 매립 (게슈탈트 시각 결합)
    var positions = [];
    var totalLen = wLen * 8 + Math.floor(Math.random()*15) + 20;
    // 단어 문자 위치 결정 (연속이 아닌 분산)
    var startPos = Math.floor(totalLen * 0.25) + Math.floor(Math.random()*(totalLen*0.3));
    for(var i=0;i<wLen;i++) positions.push(startPos + i*3);
    // 카오스 텍스트 생성
    var charIdx = 0;
    for(var p=0;p<totalLen;p++){
      if(positions.indexOf(p)>-1){
        result += hiddenWord[charIdx++];
      } else {
        // 노이즈: 특수기호 + 자모 + 숫자 혼합
        var nType = Math.floor(Math.random()*3);
        if(nType===0) result += noise[Math.floor(Math.random()*noise.length)];
        else if(nType===1) result += Math.floor(Math.random()*9);
        else result += String.fromCharCode(0x61+Math.floor(Math.random()*26));
      }
    }
    return result;
  },
  // 새 챌린지 생성
  newChallenge: function(hiddenWord){
    _MUFE.hiddenWord = hiddenWord;
    var lines = [];
    for(var i=0;i<4;i++) lines.push(_MUFE.generateChaosText(hiddenWord));
    _MUFE.currentChallenge = lines;
    return lines;
  }
};

function mufeShowAuth(){
  // 이미 인증됐으면 패스
  if(_MUFE.verified || !localStorage.getItem('_mufe_set')) return true;
  var overlay = document.getElementById('mufe-auth-overlay');
  if(overlay) overlay.style.display='flex';
  mufeRefreshChallenge();
  return false;
}

function mufeRefreshChallenge(){
  // 고정 단어 — 대표님과 Claude만 아는 비밀 (고발삼춘)
  var words = ['고발'];
  var d2 = new Date();
  var todayWord = '고발';
  _MUFE.newChallenge(todayWord);
  var disp = document.getElementById('mufe-chaos-display');
  if(!disp) return;
  disp.innerHTML = '';
  _MUFE.currentChallenge.forEach(function(line,i){
    var div = document.createElement('div');
    div.style.cssText = 'font-family:monospace;font-size:'+(i===1?'15':'12')+'px;color:rgba('+(i===1?'212,168,67':'180,200,220')+','+(i===1?'0.95':'0.45')+');letter-spacing:.08em;line-height:1.8;word-break:break-all;padding:2px 0;';
    div.textContent = line;
    disp.appendChild(div);
  });
  // 힌트 카운터
  var hint = document.getElementById('mufe-hint');
  if(hint) hint.textContent = _cgoT('시도 ') + _MUFE.attempts + ' / ' + _MUFE.maxAttempts;
}

function mufeVerify(){
  var input = document.getElementById('mufe-input');
  if(!input) return;
  var val = input.value.trim();
  if(!val){ mufeShake(); return; }

  // 개인 키워드 복호화
  var pk = '';
  try{ pk = decodeURIComponent(atob(localStorage.getItem('_mufe_pk')||'')); }catch(e){}

  // 고정 단어 — 대표님과 Claude만 아는 비밀 (고발삼춘)
  var d3 = new Date();
  var todayWord = '고발';
  var correctAnswer = pk ? todayWord + pk : todayWord; // = 고발삼춘
  // 대소문자 무시, 공백 무시
  var isCorrect = val.replace(/\s/g,'').toLowerCase() === correctAnswer.replace(/\s/g,'').toLowerCase();

  if(isCorrect){
    _MUFE.verified = true;
    _MUFE.attempts = 0;
    var overlay = document.getElementById('mufe-auth-overlay');
    if(overlay){
      overlay.style.background='rgba(52,211,153,0.08)';
      var box = document.getElementById('mufe-auth-box');
      if(box){ box.style.borderColor='rgba(52,211,153,0.5)'; box.style.boxShadow='0 0 40px rgba(52,211,153,0.3)'; }
      var status = document.getElementById('mufe-status');
      if(status){ status.textContent=_cgoT('✅ 물리적 현존성 확인 완료 — LJR 인증'); status.style.color='#34d399'; }
      setTimeout(function(){ overlay.style.display='none'; input.value=''; }, 1200);
    }
  } else {
    _MUFE.attempts++;
    mufeShake();
    var status = document.getElementById('mufe-status');
    if(_MUFE.attempts >= _MUFE.maxAttempts){
      if(status){ status.textContent=_cgoT('🚨 비정상 접근 감지 — 세션 격리 중...'); status.style.color='#f87171'; }
      // 가상 샌드박스로 유인 (공격자 자원 소모)
      setTimeout(function(){
        mufeRefreshChallenge();
        _MUFE.attempts = 0;
        input.value='';
        if(status){ status.textContent=_cgoT('🔄 새 인증 과제 생성됨'); status.style.color='rgba(240,230,200,.6)'; }
      }, 2000);
    } else {
      if(status){ status.textContent=_cgoT('❌ 인증 실패 (') + _MUFE.attempts + '/' + _MUFE.maxAttempts + ')'; status.style.color='#f87171'; }
      setTimeout(function(){ if(status) status.textContent=''; }, 1500);
    }
    var hint = document.getElementById('mufe-hint');
    if(hint) hint.textContent = _cgoT('시도 ') + _MUFE.attempts + ' / ' + _MUFE.maxAttempts;
  }
}

function mufeShake(){
  var box = document.getElementById('mufe-auth-box');
  if(!box) return;
  box.style.animation='mufeShake .4s ease';
  setTimeout(function(){ box.style.animation=''; }, 400);
}

function mufeSkip(){
  // 개인 키워드 미설정 시 건너뜀 허용
  if(!localStorage.getItem('_mufe_set')){
    var overlay = document.getElementById('mufe-auth-overlay');
    if(overlay) overlay.style.display='none';
  }
}

// 날짜 표시
function updateDate(){
  var d=new Date();
  var lang=window._LANG||'ko';
  if(lang==='ko'){
    var days=['일','월','화','수','목','금','토'];
    document.getElementById('topDate').textContent=d.getFullYear()+'년 '+(d.getMonth()+1)+'월 '+d.getDate()+'일 '+days[d.getDay()];
  } else {
    var _dn=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    var _mn=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    if(lang==='zh'||lang==='zh_HK'){
      document.getElementById('topDate').textContent=d.getFullYear()+'年'+(d.getMonth()+1)+'月'+d.getDate()+'日';
    } else if(lang==='ja'){
      document.getElementById('topDate').textContent=d.getFullYear()+'年'+(d.getMonth()+1)+'月'+d.getDate()+'日('+_dn[d.getDay()]+')';
    } else if(lang==='ru'||lang==='uk'){
      document.getElementById('topDate').textContent=d.getDate()+' '+_mn[d.getMonth()]+' '+d.getFullYear();
    } else if(lang==='ar'){
      document.getElementById('topDate').textContent=d.getDate()+'/'+(d.getMonth()+1)+'/'+d.getFullYear();
    } else {
      document.getElementById('topDate').textContent=_mn[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();
    }
  }
}

