function _tzrT(section, key) {
  var L = window._LANG||'ko';
  var pack = _TZR_I18N[L] || _TZR_I18N.en;
  return (pack[section]&&pack[section][key]) || (_TZR_I18N.ko[section][key]);
}

function _tzrUpdate(){
  var L = window._LANG||'ko';

  // ── 天: NASA 행성 에너지 ──
  (function(){
    var np = window._nasaPlanets || {};
    var tianIco, tianTxt, tianSub;
    var retroCount = 0;
    ['mercury','venus','mars','jupiter','saturn'].forEach(function(k){
      if(np[k]&&np[k].retro) retroCount++;
    });
    var sunLon = np.sun ? parseFloat(np.sun.lon||0) : 0;
    var retroSuffix = _tzrT('tian','explosion')[1];
    if(retroCount>=3){
      tianIco='☄️🔥'; tianTxt=_tzrT('tian','explosion')[0]; tianSub=retroCount+retroSuffix;
    } else if(retroCount>=1){
      tianIco='🌌⚠️'; tianTxt=_tzrT('tian','caution')[0]; tianSub=retroCount+_tzrT('tian','caution')[1];
    } else if(sunLon>=0&&sunLon<90){
      tianIco='🚀💎'; tianTxt=_tzrT('tian','peak')[0]; tianSub=_tzrT('tian','peak')[1];
    } else if(sunLon>=90&&sunLon<180){
      tianIco='✨🪐'; tianTxt=_tzrT('tian','stable')[0]; tianSub=_tzrT('tian','stable')[1];
    } else if(sunLon>=180&&sunLon<270){
      tianIco='🌠💫'; tianTxt=_tzrT('tian','change')[0]; tianSub=_tzrT('tian','change')[1];
    } else {
      tianIco='🛸⚡'; tianTxt=_tzrT('tian','active')[0]; tianSub=_tzrT('tian','active')[1];
    }
    var ti=document.getElementById('tian-ico');
    var tt=document.getElementById('tian-txt');
    var ts=document.getElementById('tian-sub');
    if(ti)ti.textContent=tianIco;
    if(tt)tt.textContent=tianTxt;
    if(ts)ts.textContent=tianSub;
  })();

  // ── 地: 날씨 ──
  (function(){
    if(window._tzrWeatherDone) {
      // 이미 날씨 데이터 있으면 언어만 업데이트
      if(window._tzrWeatherKey) {
        var k=window._tzrWeatherKey, t=window._tzrWeatherTemp;
        var chiTxt=_tzrT('chi',k)[0]+(t?' · '+t+'°C':'');
        var chiSub=_tzrT('chi',k)[1];
        var ct=document.getElementById('chi-txt');
        var cs=document.getElementById('chi-sub');
        if(ct)ct.textContent=chiTxt;
        if(cs)cs.textContent=chiSub;
      }
      return;
    }
    if(window._cgoLat && window._cgoLon){
      fetch('https://wttr.in/?format=j1')
      .then(function(r){return r.json();})
      .then(function(d){
        window._tzrWeatherDone=true;
        var cur=d.current_condition&&d.current_condition[0];
        if(!cur){_tzrWeatherFallback();return;}
        var code=parseInt(cur.weatherCode||800);
        var tempC=cur.temp_C||'--';
        var humidity=cur.humidity||'--';
        var chiIco, wKey;
        if(code===800){chiIco='☀️✨'; wKey='sunny';}
        else if(code<=802){chiIco='⛅💨'; wKey='cloudy';}
        else if(code<=804){chiIco='☁️🌫️'; wKey='overcast';}
        else if(code<=531){chiIco='🌧️💧'; wKey='rain';}
        else if(code<=622){chiIco='❄️🌨️'; wKey='snow';}
        else if(code<=232){chiIco='⚡🌩️'; wKey='thunder';}
        else{chiIco='🌤️'; wKey='default';}
        window._tzrWeatherKey = wKey;
        window._tzrWeatherTemp = tempC;
        var chiTxt = _tzrT('chi',wKey)[0] + (wKey!=='default'?' · '+tempC+'°C':''+tempC+'°C · '+humidity+'%');
        var chiSub = _tzrT('chi',wKey)[1];
        var ci=document.getElementById('chi-ico');
        var ct=document.getElementById('chi-txt');
        var cs=document.getElementById('chi-sub');
        if(ci)ci.textContent=chiIco;
        if(ct)ct.textContent=chiTxt;
        if(cs)cs.textContent=chiSub;
      }).catch(function(){_tzrWeatherFallback();});
    } else {
      _tzrWeatherFallback();
    }
  })();

  // ── 人: 생체 데이터 ──
  (function(){
    var bio = window._bioFinalData || {};
    var ili = window.calcResult ? window.calcResult.ili : 0;
    var renIco,renTxt,renSub;
    if(!bio.bpm&&!ili){
      renIco='🧬'; renTxt=_tzrT('ren','waiting')[0]; renSub=_tzrT('ren','waiting')[1];
    } else {
      var eng = bio.eng||0;
      var bpm = bio.bpm||0;
      var hrv = bio.hrv||0;
      if(eng>=85||ili>=85){
        renIco='💹💰🤑'; renTxt=_tzrT('ren','invest')[0]; renSub=_tzrT('ren','invest')[1]+ili;
      } else if(eng>=70||ili>=70){
        renIco='⚡💪'; renTxt=_tzrT('ren','active')[0]; renSub=_tzrT('ren','active')[1]+bpm+'BPM · HRV '+hrv;
      } else if(eng>=55||ili>=55){
        renIco='🧘‍♂️☕'; renTxt=_tzrT('ren','watch')[0]; renSub=_tzrT('ren','watch')[1];
      } else {
        renIco='😴💤'; renTxt=_tzrT('ren','rest')[0]; renSub=_tzrT('ren','rest')[1];
      }
    }
    var ri=document.getElementById('ren-ico');
    var rt=document.getElementById('ren-txt');
    var rs=document.getElementById('ren-sub');
    if(ri)ri.textContent=renIco;
    if(rt)rt.textContent=renTxt;
    if(rs)rs.textContent=renSub;
  })();
}

function _tzrWeatherFallback(){
  var hr=new Date().getHours();
  var chiIco, wKey;
  if(hr>=6&&hr<=10){chiIco='🌅✨'; wKey='morning';}
  else if(hr>=11&&hr<=14){chiIco='☀️🔥'; wKey='noon';}
  else if(hr>=15&&hr<=18){chiIco='🌤️💨'; wKey='afternoon';}
  else if(hr>=19&&hr<=22){chiIco='🌇🌙'; wKey='evening';}
  else{chiIco='🌙⭐'; wKey='night';}
  var chiTxt=_tzrT('chi',wKey)[0];
  var chiSub=_tzrT('chi',wKey)[1];
  var ci=document.getElementById('chi-ico');
  var ct=document.getElementById('chi-txt');
  var cs=document.getElementById('chi-sub');
  if(ci)ci.textContent=chiIco;
  if(ct)ct.textContent=chiTxt;
  if(cs)cs.textContent=chiSub;
}

// 별 생성
function createStars(){
  var c=document.getElementById('stars');
  for(var i=0;i<80;i++){
    var s=document.createElement('div');
    s.className='star';
    var size=Math.random()*2+0.5;
    s.style.cssText='width:'+size+'px;height:'+size+'px;left:'+(Math.random()*100)+'%;top:'+(Math.random()*100)+'%;--d:'+(Math.random()*3+2)+'s;--delay:'+(-Math.random()*5)+'s';
    c.appendChild(s);
  }
}

