function cgoShowSoftBanner(pageId) {
  var old = document.getElementById('cgo-soft-banner');
  if (old) old.remove();
  if (window.calcResult && window.calcResult.domOh) return;
  var label = pageId === 'stock' ? '📈 주식 에너지 예측' : '🔮 1대1 고민 상담';

  var banner = document.createElement('div');
  banner.id = 'cgo-soft-banner';
  banner.style.cssText = 'margin:0 0 14px;padding:12px 14px;background:rgba(251,191,36,0.07);border:1px solid rgba(251,191,36,0.25);border-radius:12px;display:flex;align-items:flex-start;gap:10px;';

  // 아이콘
  var ico = document.createElement('div');
  ico.style.cssText = 'font-size:20px;flex-shrink:0;';
  ico.textContent = '💡';

  // 본문
  var body = document.createElement('div');
  body.style.cssText = 'flex:1;';

  var title = document.createElement('div');
  title.style.cssText = 'font-size:12px;font-weight:700;color:#fbbf24;margin-bottom:5px;';
  title.textContent = label + ' 정확도를 높이려면';

  var desc = document.createElement('div');
  desc.style.cssText = 'font-size:11px;color:rgba(251,191,36,0.75);line-height:1.7;';
  desc.innerHTML = '🏠 대시보드에서 정보 입력 후 ⚡ 자동 계산을 먼저 완료하면<br>50대 역학 중이 <b style="color:#fbbf24;">내 사주에 맞게 최적화</b>됩니다.';

  var goBtn = document.createElement('button');
  goBtn.style.cssText = 'margin-top:8px;padding:5px 14px;border-radius:7px;background:rgba(251,191,36,0.15);border:1px solid rgba(251,191,36,0.35);color:#fbbf24;font-size:11px;font-weight:700;cursor:pointer;font-family:\'Noto Sans KR\',sans-serif;';
  goBtn.textContent = _cgoT('지금 입력하러 가기 →');
  goBtn.onclick = function(){ cgoSoftGo('dashboard'); };

  body.appendChild(title);
  body.appendChild(desc);
  body.appendChild(goBtn);

  // 닫기
  var closeBtn = document.createElement('div');
  closeBtn.style.cssText = 'font-size:16px;color:rgba(180,200,216,0.8);cursor:pointer;flex-shrink:0;padding:2px 4px;';
  closeBtn.textContent = '✕';
  closeBtn.onclick = function(){ banner.remove(); };

  banner.appendChild(ico);
  banner.appendChild(body);
  banner.appendChild(closeBtn);

  var pg = document.getElementById('page-' + pageId);
  if (pg) pg.insertBefore(banner, pg.firstChild);
}

function cgoSoftGo(pageId) {
  /* ★ C-62: nav-btn(🏠 Dashboard 등)으로 나갈 때도 눈건강 정리 — cgoSoftGo는 cgoGoPage를 안 거쳐서 page-c44-eye가 안 닫히던 진짜 원인 fix */
  try{ if(pageId!=='c44-eye'){ try{ document.querySelectorAll('video').forEach(function(_vv){ if(_vv.srcObject){ try{_vv.srcObject.getTracks().forEach(function(t){t.stop();});}catch(e){} _vv.srcObject=null; } }); }catch(e){} var _ce8=document.getElementById('page-c44-eye'); if(_ce8){ _ce8.style.display='none'; if(_ce8.classList)_ce8.classList.remove('active'); var _ev8=document.getElementById('eye-video'); if(_ev8&&_ev8.srcObject){ try{_ev8.srcObject.getTracks().forEach(function(t){t.stop();});}catch(e){} _ev8.srcObject=null; } if(window.eyeState){ window.eyeState.started=false; if(window.eyeState.qTimerInterval)clearInterval(window.eyeState.qTimerInterval); if(window.eyeState.rppgInterval)clearInterval(window.eyeState.rppgInterval); if(window.eyeState.stream){ try{window.eyeState.stream.getTracks().forEach(function(t){t.stop();});}catch(e){} window.eyeState.stream=null; } } if(window._eye108State&&window._eye108State.feedInterval){ clearInterval(window._eye108State.feedInterval); window._eye108State.feedInterval=null; } var _pt8=document.getElementById('pageTitleText'); if(_pt8){ _pt8.style.display='none'; _pt8.textContent=''; } } } }catch(e){}
  var b = document.getElementById('cgo-soft-banner');
  if (b) b.remove();
  document.querySelectorAll('.nav-btn').forEach(function(x){x.classList.remove('active');});
  var btn = document.querySelector('[data-page="'+pageId+'"]');
  if (btn) btn.classList.add('active');
  document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active');});
  var pg = document.getElementById('page-'+pageId);
  if (pg) pg.classList.add('active');
  var nb = document.getElementById('nasaMiniBar');
  var pt = document.getElementById('pageTitleText');
  if (pageId === 'dashboard') {
    if (nb) nb.style.display = 'flex';
    if (pt) { pt.style.display = 'none'; pt.textContent = ''; }
  }
  // ✅ 커플 페이지 진입 시 대시보드 데이터 자동 연동
  if (pageId === 'couple') {
    setTimeout(function(){ if(typeof cplAutoFill==='function') cplAutoFill(); }, 200);
  }
  if (pageId === 'gmd') setTimeout(function(){ if(typeof _cgoGmdIntroPopup==='function') _cgoGmdIntroPopup(); },100);
  window._cgoLastPage = pageId;
  // 페이지 이동 후 번역
  if (window._LANG && window._LANG !== 'ko') {
    var _tLang = window._LANG;
    var _p3 = CGO_I18N[_tLang];
    if (_p3) {
      // 정적 data-i18n 즉시 교체
      document.querySelectorAll('[data-i18n]').forEach(function(el){
        var k=el.getAttribute('data-i18n'); if(_p3[k]!==undefined) el.textContent=_p3[k];
      });
      document.querySelectorAll('[data-i18n-html]').forEach(function(el){
        var k=el.getAttribute('data-i18n-html'); if(_p3[k]!==undefined) el.innerHTML=_p3[k];
      });
      // AI 번역 — 현재 활성 페이지만 번역 (빠름)
      setTimeout(function(){
        if(window._LANG !== _tLang) return;
        window._transCache = {};
        var _pg = document.getElementById('page-'+pageId);
        if(_pg && typeof _cgoAiTranslatePage === 'function') {
          _cgoAiTranslatePage(_tLang, _p3, _pg);
        } else if(typeof _cgoAiTranslate === 'function') {
          _cgoAiTranslate(_tLang, _p3);
        }
      }, 150);
      // 2차: 동적 생성 텍스트 재번역
      setTimeout(function(){
        if(window._LANG !== _tLang) return;
        window._cgoTransRunning = null;
        if(typeof _cgoAiTranslate === 'function') _cgoAiTranslate(_tLang, _p3);
      }, 1500);
    }
  }
}
