// 현재 언어
window._cgoLang = localStorage.getItem('cgo_lang') || 'ko';

// 언어팩 현재 값 가져오기
function _t(key, subkey) {
  var lp = _LANG_PACK[window._cgoLang] || _LANG_PACK['ko'];
  if (subkey) return (lp[key] && lp[key][subkey]) || (_LANG_PACK['ko'][key] && _LANG_PACK['ko'][key][subkey]) || key;
  return lp[key] || _LANG_PACK['ko'][key] || key;
}

// 언어 메뉴 토글
// [중복 toggleLangMenu/setLang 제거됨]

// 국가별 역학 강조 순서
function _applyLangEmphasis(lang) {
  // DOM 이동 없이 — 언어별 강조 색상만 적용
  try {
    var eastHdr = document.querySelector('#section18algo [style*="a78bfa"]');
    var westHdr = document.querySelector('#section18algo [style*="fbbf24"]');
    if (lang === 'en') {
      // 영어권: 서양 역학 헤더 금색 강조
      if (westHdr) westHdr.style.color = '#d4a843';
      if (eastHdr) eastHdr.style.color = 'rgba(167,139,250,.6)';
    } else {
      // 동양권: 동양 역학 헤더 강조 (기본)
      if (eastHdr) eastHdr.style.color = '#a78bfa';
      if (westHdr) westHdr.style.color = 'rgba(251,191,36,.8)';
    }
  } catch(e) {}
}

// 초기 언어 적용 (페이지 로드 시)
document.addEventListener('DOMContentLoaded', function(){
  // ✅ 핵심: 대문(phase0)이 표시 중이면 setLang 실행 안 함
  // — 대문에서 사용자가 직접 선택 → p0Enter에서 저장 → _cgoEntranceDone에서 적용
  var p0 = document.getElementById('phase0');
  var p0Visible = p0 && p0.style.display !== 'none' && p0.offsetParent !== null;

  if (!p0Visible) {
    // 새로고침으로 대문 건너뛴 경우만 — 저장된 언어 복원
    var saved = localStorage.getItem('cgo_lang') || 'ko';
    if (saved && saved !== 'ko' && typeof setLang === 'function') {
      try{ setLang(saved); }catch(e){}
      requestAnimationFrame(function(){ requestAnimationFrame(function(){
        try{ if(window._cgoLangGuardOff) window._cgoLangGuardOff(); }catch(e){}
      }); });
    }
  }
  // (대문이 보이는 경우는 _cgoEntranceDone에서 처리)

  // ── 프로필 저장값 자동 로드 ──────────────────────────
  (function _loadSavedProfile(){
    var setVal = function(id,v){ var e=document.getElementById(id); if(e&&v) e.value=v; };
    var setTxt = function(id,v){ var e=document.getElementById(id); if(e&&v) e.textContent=v; };

    // 이름
    var sn = localStorage.getItem('cgo_prof_name');
    if(sn){
      setVal('prof-name', sn);
      setTxt('profName', sn);
      setTxt('topName',  sn);
      setTxt('topAvatar', sn.charAt(0));
      setTxt('sbAvatar',  sn.charAt(0));
      setVal('ipName', sn);
    }

    // 생년월일 (년/월/일 분리)
    var sy = localStorage.getItem('cgo_prof_birth_y');
    var sm = localStorage.getItem('cgo_prof_birth_m');
    var sd = localStorage.getItem('cgo_prof_birth_d');
    if(sy){ setVal('prof-birth-y', sy); setVal('ipBirthY', sy); }
    if(sm){ setVal('prof-birth-m', sm); setVal('ipBirthM', sm); }
    if(sd){ setVal('prof-birth-d', sd); setVal('ipBirthD', sd); }
    if(sy && sm && sd){
      var dateStr = sy+'-'+sm.padStart(2,'0')+'-'+sd.padStart(2,'0');
      setVal('ipBirth', dateStr);
      setVal('prof-birth', dateStr);
    }

    // 출생 시간
    var st = localStorage.getItem('cgo_prof_time');
    if(st){ setVal('prof-time', st); setVal('ipTime', st); }

    // 성별
    var sg = localStorage.getItem('cgo_prof_gender');
    if(sg){
      setVal('prof-gender', sg);
      var gSel = document.getElementById('ipGender');
      if(gSel) gSel.value = sg;
    }

    // 출생지 → 프로필 + 대시보드
    var bp = localStorage.getItem('cgo_birth_place');
    if(bp){ setVal('prof-birth-place', bp); setVal('ipBirthPlace', bp); }

    // 현재 거주지 → 프로필 + 대시보드
    var cp = localStorage.getItem('cgo_cur_place');
    if(cp){
      setVal('prof-cur-place', cp);
      setTimeout(function(){ setVal('ipCurPlace', cp); }, 300);
    }

    // syncBirthField 동기화
    setTimeout(function(){
      if(typeof syncBirthField === 'function') syncBirthField();
    }, 400);
  })();
});


// ══ goMusic — 나의 주파수 음악 전용 진입 함수 ══
var _pmSiJin = 0;
var _pmSeason = '봄';

function goMusic(){
  // 페이지 전환
  document.querySelectorAll('.nav-btn').forEach(function(b){b.classList.remove('active');});
  var _nb=document.querySelector('[data-page="music"]');
  if(_nb) _nb.classList.add('active');
  document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active');});
  var _pg=document.getElementById('page-music');
  if(_pg) _pg.classList.add('active');
  var _tx=document.getElementById('pageTitleText');
  if(_tx){_tx.style.display='block';_tx.textContent=_cgoT('🎵 나의 주파수 음악');}
  var _nb2=document.getElementById('nasaMiniBar');
  if(_nb2) _nb2.style.display='none';

  // 시진·계절 초기화
  _pmSiJin = getCurrentSiJin ? getCurrentSiJin() : Math.floor((new Date().getHours()+1)/2)%12;
  _pmSeason = getCurrentSeason ? getCurrentSeason() : '봄';
  pmUpdateSiJinUI(); pmUpdateSeasonUI(); pmUpdateTimeLabel();

  // 잠금 결정
  var bfd=window._bioFinalData||{};
  var scanned=window._baiScanned||(bfd.fci>0||bfd.hrv>0);
  var hasCalc=!!(window.calcResult&&window.calcResult.domOh);
  var lock=document.getElementById('pm-lock');
  var box=document.getElementById('pm-box');
  var stage=document.getElementById('pm-stage');

  if(hasCalc||scanned){
    if(lock) lock.style.display='none';
    if(box)  box.style.display='block';
    if(stage){
      if(scanned){
        stage.textContent=_cgoT('🧬 2단계: 생체신호 × 역학 융합 정밀 가이드');
        stage.style.color='#34d399';
        stage.style.background='rgba(52,211,153,.1)';
        stage.style.borderColor='rgba(52,211,153,.3)';
      } else {
        stage.textContent=_cgoT('📜 1단계: 만세력 × NASA 실시간 기반 추천');
        stage.style.color='#d4a843';
        stage.style.background='rgba(212,168,67,.1)';
        stage.style.borderColor='rgba(212,168,67,.25)';
      }
    }
    var _rt=document.getElementById('pm-refresh');
    if(_rt){
      var _n=new Date();
      var _sjn=['자시(23~1)','축시(1~3)','인시(3~5)','묘시(5~7)','진시(7~9)','사시(9~11)','오시(11~13)','미시(13~15)','신시(15~17)','유시(17~19)','술시(19~21)','해시(21~23)'];
      _rt.textContent=_n.getHours()+':'+String(_n.getMinutes()).padStart(2,'0')+' · '+_sjn[Math.floor((_n.getHours()+1)/2)%12]+' 기준';
    }
    pmRender();
  } else {
    if(lock) lock.style.display='block';
    if(box)  box.style.display='none';
  }
}

function pmSetSiJin(idx){
  _pmSiJin=idx;
  pmUpdateSiJinUI();
  pmRender();
}
function pmSetSeason(s){
  _pmSeason=s;
  pmUpdateSeasonUI();
  pmRender();
}
function pmUpdateSiJinUI(){
  for(var i=0;i<12;i++){
    var b=document.getElementById('pmSj'+i);
    if(b){
      b.style.background=i===_pmSiJin?'rgba(212,168,67,.2)':'rgba(255,255,255,.04)';
      b.style.borderColor=i===_pmSiJin?'rgba(212,168,67,.6)':'rgba(255,255,255,.1)';
      b.style.color=i===_pmSiJin?'#d4a843':'rgba(240,230,200,.5)';
    }
  }
}
function pmUpdateSeasonUI(){
  ['봄','여름','가을','겨울'].forEach(function(s){
    var b=document.getElementById('pmSs'+s);
    if(b){
      b.style.background=s===_pmSeason?'rgba(56,189,248,.15)':'rgba(255,255,255,.04)';
      b.style.borderColor=s===_pmSeason?'rgba(56,189,248,.5)':'rgba(255,255,255,.1)';
      b.style.color=s===_pmSeason?'#38bdf8':'rgba(240,230,200,.5)';
    }
  });
}
function pmUpdateTimeLabel(){
  var _t=document.getElementById('pm-time');
  if(!_t) return;
  var _n=new Date();
  _t.textContent=_n.getHours()+':'+String(_n.getMinutes()).padStart(2,'0');
}

function pmRender(){
  var r=window.calcResult; if(!r) return;
  if(!window.MUSIC_DB) return;
  var cards=document.getElementById('pm-cards');
  var mlist=document.getElementById('pm-list');
  if(!cards||!mlist) return;

  var oh=r.domOh||'목';
  var bfd=window._bioFinalData||{};
  var bpm=(bfd.bpm||72), hrv=(bfd.hrv||45), fci=(bfd.fci||80), bli=(bfd.bli||75);
  var eng=r.ili||70, ili=r.ili||70;
  var _now=new Date();
  var _slot=_now.getHours()*6+Math.floor(_now.getMinutes()/10);
  var _seed=rng(
    (_now.getFullYear()*10000+(_now.getMonth()+1)*100+_now.getDate())
    +_pmSiJin*4999+_slot*997
    +(bpm*13+fci*7)|0
  );
  var bs={bpm:bpm,hrv:hrv,fci:fci,eng:eng,ili:ili,oh:oh,
          dateSeed:_seed,siJin:_pmSiJin,season:_pmSeason,bli:bli,timeSlot:_slot};

  cards.innerHTML='<div style="font-size:12px;color:rgba(240,230,200,.6);text-align:center;padding:12px">⏰ '+_pmSeason+' · 역학 분석 중...</div>';
  mlist.style.display='none'; mlist.innerHTML='';

  var scores=[];
  // ★ 기준서 v1.0 — YEOKAK ID → s01~s19 매핑 테이블
  var _s18map = {
    saju:'s01', jami:'s02', gim:'s05',  gusung:'s19', iching:'s15',
    numer:'s08', naming:'s11', solar:'s03', transit:'s06', yuk:'s07',
    feng:'s09', kabala:'s10', house:'s12', taeeul:'s13', taro:'s16',
    synastry:'s14', gwan:'s17', palm:'s18'
  };
  var _s18 = (r.scores && r.scores.s18) ? r.scores.s18 : {};

  // ★ 스캔 미완료 시 관상·손금 카드 제외 (사실 기반 원칙)
  var _scanned = window._baiScanned || (bfd.fci>0 || bfd.hrv>0);
  var _yeokak = MUSIC_DB.YEOKAK.filter(function(yk){
    if(!_scanned && (yk.id==='gwan' || yk.id==='palm')) return false;
    return true;
  });
  _yeokak.forEach(function(yk,i){
    setTimeout(function(){
      var res=yk.analyze(bs);
      // ★ 기준서 v1.0 점수 우선 적용 (없으면 음악 자체 계산값)
      var _sKey = _s18map[yk.id];
      var _baseScore = res.score;
      scores.push(_baseScore);
      var sc=_baseScore;
      var scc=sc>=85?'#34d399':sc>=75?'#d4a843':'#94a3b8';
      var card=document.createElement('div');
      card.className='bsmc-card';
      var cardId='bsmc-card-'+yk.id;
      card.id=cardId;
      card.innerHTML=
        '<div class="bsmc-head">'+
          '<div class="bsmc-ico" style="background:'+yk.bg+';border:1px solid '+yk.border+'">'+yk.emoji+'</div>'+
          '<div style="flex:1"><div class="bsmc-title">'+yk.name+'</div><div class="bsmc-sub">'+yk.sub+'</div></div>'+
          '<div style="display:flex;align-items:center;gap:6px;">'+
            '<div class="bsmc-score"><div class="bsmc-score-v" style="color:'+scc+'">'+sc+'</div><div class="bsmc-score-l">운 지수</div></div>'+
            '<button class="bsmc-refresh" data-id="'+yk.id+'" onclick="event.stopPropagation();pmRefreshCard(\''+yk.id+'\')" style="background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.15);border-radius:8px;color:rgba(240,230,200,.5);font-size:13px;width:28px;height:28px;cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center;">↺</button>'+
          '</div>'+
        '</div>'+
        '<div class="bsmc-body">'+
          '<div class="bsmc-analysis">'+res.detail+'</div>'+
          res.rows.map(function(row){return'<div class="bsmc-row"><div class="bsmc-row-i">'+row.i+'</div><div class="bsmc-row-t">'+row.t+'</div></div>';}).join('')+
        '</div>';
      card.querySelector('.bsmc-head').addEventListener('click',function(){card.classList.toggle('open');});
      if(i===0) cards.innerHTML='';
      cards.appendChild(card);
      if(i===_yeokak.length-1){
        setTimeout(function(){
          var avg=Math.round(scores.reduce(function(a,b){return a+b;},0)/scores.length);
          pmShowList(mlist,bs,avg);
        },600);
      }
    },i*350+300);
  });
}

function pmRefreshCard(ykId){
  var card=document.getElementById('bsmc-card-'+ykId);
  if(!card||!window.MUSIC_DB) return;
  var yk=MUSIC_DB.YEOKAK.filter(function(y){return y.id===ykId;})[0];
  if(!yk) return;
  var r=window.calcResult; if(!r) return;
  var bfd=window._bioFinalData||{};
  var bpm=(bfd.bpm||72),hrv=(bfd.hrv||45),fci=(bfd.fci||80),bli=(bfd.bli||75);
  var _now=new Date();
  var _slot=_now.getHours()*6+Math.floor(_now.getMinutes()/10);
  var _seed=rng((_now.getFullYear()*10000+(_now.getMonth()+1)*100+_now.getDate())+_pmSiJin*4999+_slot*997+(bpm*13+fci*7)|0);
  var bs={bpm:bpm,hrv:hrv,fci:fci,eng:r.ili||70,ili:r.ili||70,oh:r.domOh||'목',
          dateSeed:_seed+Math.round(Math.random()*9999),siJin:_pmSiJin,season:_pmSeason,bli:bli,timeSlot:_slot};
  // 새로고침 버튼 스핀
  var btn=card.querySelector('.bsmc-refresh');
  if(btn){btn.style.transform='rotate(360deg)';btn.style.transition='transform .5s';
    setTimeout(function(){btn.style.transform='';btn.style.transition='';},600);}
  var res=yk.analyze(bs);
  var sc=res.score;
  var scc=sc>=85?'#34d399':sc>=75?'#d4a843':'#94a3b8';
  card.querySelector('.bsmc-score-v').textContent=sc;
  card.querySelector('.bsmc-score-v').style.color=scc;
  card.querySelector('.bsmc-analysis').innerHTML=res.detail;
  var rows=card.querySelectorAll('.bsmc-row');
  rows.forEach(function(el){el.remove();});
  var body=card.querySelector('.bsmc-body');
  res.rows.forEach(function(row){
    var d=document.createElement('div'); d.className='bsmc-row';
    d.innerHTML='<div class="bsmc-row-i">'+row.i+'</div><div class="bsmc-row-t">'+row.t+'</div>';
    body.appendChild(d);
  });
}

function pmShowList(el,bs,avg){
  // _showMusicList 재활용
  if(typeof _showMusicList==='function'){
    _showMusicList(el,bs,avg);
    el.style.display='block';
  }
}


