    +'<button id="cgo-vision-shoot" onclick="_cgoVisionShoot()" style="flex:1;padding:14px;background:linear-gradient(135deg,'+color+','+color+'88);border:none;border-radius:14px;color:#000;font-size:14px;font-weight:900;cursor:pointer;display:none;">📸 촬영 & 분석</button>'
