  // SVG 레이더
  function _mkRadar(scores,labels,color){
    var cx=110,cy=110,rr=78,n=scores.length;
    var pts=scores.map(function(s,i){var a=(Math.PI*2/n)*i-Math.PI/2,rv=rr*(Math.max(0,Math.min(100,s))/100);return[(cx+rv*Math.cos(a)).toFixed(1),(cy+rv*Math.sin(a)).toFixed(1)];});
    var bg=scores.map(function(_,i){var a=(Math.PI*2/n)*i-Math.PI/2;return[(cx+rr*Math.cos(a)).toFixed(1),(cy+rr*Math.sin(a)).toFixed(1)];});
    var lp=scores.map(function(_,i){var a=(Math.PI*2/n)*i-Math.PI/2;return[(cx+(rr+20)*Math.cos(a)).toFixed(1),(cy+(rr+20)*Math.sin(a)).toFixed(1)];});
    var h='<svg width="220" height="220" viewBox="0 0 220 220" style="display:block;margin:0 auto">';
    [.33,.66,1].forEach(function(f){var gp=bg.map(function(p){return[(cx+(p[0]-cx)*f).toFixed(1),(cy+(p[1]-cy)*f).toFixed(1)];});h+='<polygon points="'+gp.map(function(p){return p.join(',');}).join(' ')+'" fill="none" stroke="rgba(255,255,255,.08)" stroke-width="1"/>';});
    bg.forEach(function(p){h+='<line x1="'+cx+'" y1="'+cy+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="rgba(255,255,255,.06)" stroke-width="1"/>';});
    h+='<polygon points="'+pts.map(function(p){return p.join(',');}).join(' ')+'" fill="'+color+'22" stroke="'+color+'" stroke-width="2" stroke-linejoin="round"/>';
    pts.forEach(function(p){h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3.5" fill="'+color+'"/>';});
    labels.forEach(function(lb,i){var p=lp[i];var ax=parseFloat(p[0]);var anc=ax<cx-6?'end':ax>cx+6?'start':'middle';h+='<text x="'+p[0]+'" y="'+p[1]+'" text-anchor="'+anc+'" dominant-baseline="middle" font-size="9" fill="rgba(240,230,200,.65)">'+lb+'</text>';});
    return h+'</svg>';
  }

