        + '<div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;">'
        +   '<div style="width:44px;height:44px;border-radius:12px;background:'+d.bg+';border:1px solid '+d.border+';display:flex;align-items:center;justify-content:center;font-size:20px;color:'+d.color+';">'+d.icon+'</div>'
        +   '<div style="flex:1;font-size:15px;font-weight:800;color:'+d.color+';">'+d.title+'</div>'
        +   '<button id="cgo-topic-popup-close" style="width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.08);border:none;color:#94a3b8;font-size:16px;cursor:pointer;">✕</button>'
        + '</div>'
