  pop.appendChild(hdr);

  // 배지 행
  var badges = document.createElement('div');
  badges.style.cssText = 'padding:8px 14px;display:flex;gap:5px;flex-wrap:wrap;flex-shrink:0;';
  var badgeList = [];
  badgeList.push({t:oh+'('+ohK[oh]+') 일간', c:c.color, b:'rgba('+c.rgb+',.1)', bc:'rgba('+c.rgb+',.3)'});
  if(num>=2) badgeList.push({t:'🛸 NASA 실시간', c:'#38bdf8', b:'rgba(56,189,248,.1)', bc:'rgba(56,189,248,.3)'});
